-- ====================================================================
-- SejarahWira  |  ERA 6: Perayaan Masyarakat di Malaysia  |  seed_era6.sql
-- 3 naratif (6 + 6 + 6 babak = 18 babak), setiap babak ada 1 quest, serta 50 soalan.
--
-- SETIAP naratif merangkumi enam topik yang sama: (1) perayaan utama, (2) tujuan perayaan, (3) kad ucapan dan foto
-- keluarga dahulu dan kini, (4) kolam Deepavali dan makan besar Tahun Baharu Cina, (5) kuih-muih dan amalan yang kekal,
-- (6) Hari Gawai dan Pesta Kaamatan (Unduk Ngadau). Naratif hanya berbeza pada peranan, suara, watak sampingan dan jenis cabaran.
--
-- Pelajar MERASUK jasad watak rekaan (peranan naratif):
--   Naratif 1 (Bengkel Kraf Seribu Perayaan)   = Penggiat Kraf Perayaan (NPC 101)
--   Naratif 2 (Pulang Beraya Bersama Nenek)    = Ibu Kini (NPC 102)
--   Naratif 3 (Kedai Seribu Perayaan)          = Peniaga Rumah Kedai (NPC 103)
-- Baris dialog tanpa penutur (npcID NULL) ialah baris "Pemain" / "kau" yang dituturkan tokoh peranan.
-- Baris naratif tanpa babak (sceneID NULL): 1 = tugas bersejarah, 2 = pembuka pengajaran,
--   3 = pengenalan peranan oleh Pendekar Bayang.
-- Setiap quest ada "aftermath" (Akibat jika salah), pilihan salah jenis 3/5 ada "consequence",
-- dan satu "Giliran Anda" (turns). Data sahaja (tiada jadual atau lajur baharu).
-- Lencana, artifak dan kemajuan era TIDAK disentuh.
--
-- Jalankan SELEPAS seed.sql (tiada NPC sedia ada diperlukan; NPC 101-114 dibuat di sini):
--   mysql --default-character-set=utf8mb4 -u root -p <nama_db> < database/seed_era6.sql
-- Selamat dijalankan berulang kali (kandungan Era 6 lama dipadam dahulu). Era lain tidak disentuh.
--
-- NOTA: nama perayaan Genggulang, Hari Moyang, Tahon Baro, Jis Pai, Tahun Bahauk, Tawun Empai dan San Pedro disebut mengikut bahan asal; tiada huraian tambahan dibuat.
-- ====================================================================
SET NAMES utf8mb4;
START TRANSACTION;

-- 1. Buang kandungan Era 6 lama (babak, dialog, quest, sokongan dipadam sekali: ON DELETE CASCADE).
DELETE FROM Narrative WHERE eraID = 6;

-- 2. NPC baharu Era 6 (nama fail gambar mengikut folder npc sebenar).
ON DUPLICATE KEY UPDATE name = VALUES(name), biography = VALUES(biography), contribution = VALUES(contribution), asset = VALUES(asset);

-- 3. Naratif

-- 4. Babak (sceneStoryline = kad garis masa dalam suara "kau"; asset = latar belakang)

-- 5. Quest (1 Susun Garis Masa, 2 Cari Bukti, 3 Bantu Tokoh, 4 Padanan, 5 Nyahkod Clue)
--    instruction = taklimat misi, description = objektif pembelajaran

-- 6. Sokongan: baris babak = petunjuk babak; baris quest = bisikan (hint), catatan diari (explanation), pujian (feedback)

-- 7. Dialog: baris peranan (tanpa babak) dan dialog babak

-- 8. Bank soalan Era 6 (50 soalan aneka pilihan, ID 601-650)
ON DUPLICATE KEY UPDATE eraID = VALUES(eraID);

DELETE FROM Question WHERE bankID = 6;


COMMIT;