INSERT INTO NPC (npcID, name, biography, contribution, asset) VALUES
(101, 'Penggiat Kraf Perayaan', 'Penggiat kraf yang membuat hiasan perayaan pelbagai kaum dengan tangan sendiri (watak rekaan).', 'Memelihara kraf dan tradisi perayaan supaya semua kaum mengenali perayaan jiran mereka.', 'penggiat_kraf_perayaan_tradisional.png'),
(102, 'Ibu Kini', 'Ibu moden yang membawa anak-anaknya pulang beraya ke kampung dan bertanya tentang cara dahulu (watak rekaan).', 'Menghubungkan cara sambutan dahulu dengan cara kini untuk generasi muda.', 'ibu_kini.png'),
(103, 'Peniaga Rumah Kedai', 'Peniaga yang menjual kad, kuih dan hiasan untuk semua perayaan sepanjang tahun (watak rekaan).', 'Menyediakan keperluan perayaan semua kaum dan mengenali setiap pelanggannya.', 'peniaga_rumah_kedai.png'),
(104, 'Aishah', 'Gadis Muslim yang peramah dan petah bertanya (watak rekaan).', 'Mewakili perayaan Hari Raya Aidilfitri dan Aidiladha.', 'gadis_melayu.png'),
(105, 'Kavitha', 'Gadis India yang ceria dan suka melukis kolam (watak rekaan).', 'Mewakili perayaan Deepavali dan Thaipusam.', 'gadis_india.png'),
(106, 'Ah Meng', 'Pemuda Cina yang bertenaga dan suka bergurau (watak rekaan).', 'Mewakili perayaan Tahun Baharu Cina.', 'lengchai_cina.png'),
(107, 'Mei Ling', 'Gadis Buddha yang lembut tetapi bijak berjenaka (watak rekaan).', 'Mewakili sambutan Hari Wesak.', 'amoi_cina.png'),
(108, 'Daniel', 'Pemuda Sarawak yang mesra dan suka bergurau (watak rekaan).', 'Mewakili sambutan Krismas dan Hari Gawai.', 'orang_sarawak.png'),
(109, 'Linda', 'Gadis Kadazandusun yang bersemangat dan petah bercerita (watak rekaan).', 'Mewakili Pesta Kaamatan dan Unduk Ngadau.', 'gadis_sabah.png'),
(110, 'Harjit', 'Pemuda Sikh yang tenang dan ramah (watak rekaan).', 'Mewakili sambutan Vaisakhi.', 'jejaka_india.png'),
(111, 'Apai Jelani', 'Orang tua Iban yang mesra dan pandai bercerita (watak rekaan).', 'Mewakili Hari Gawai oleh petani kaum Dayak.', 'sarawakian.png'),
(112, 'Nenek Dahulu', 'Warga emas yang mengingati cara beraya pada zaman dahulu (watak rekaan).', 'Menceritakan cara sambutan perayaan dahulu kepada cucu-cucu.', 'nenek_dahulu.png'),
(113, 'Murid Sekolah', 'Murid yang gemar bertanya dan memegang telefon pintar (watak rekaan).', 'Mewakili generasi muda yang meraikan perayaan dengan cara kini.', 'budak_gajet.png'),
(114, 'Pak Nelayan', 'Nelayan peramah yang bersyukur dengan hasil laut (watak rekaan).', 'Mewakili sambutan San Pedro yang mensyukuri hasil laut.', 'nelayan.png')
INSERT INTO Narrative (narrativeID, narrativeTitle, eraID, summary) VALUES
(601, 'Bengkel Kraf Seribu Perayaan', 6, 'Masuki peranan penggiat kraf perayaan yang membuat hiasan untuk semua kaum. Dalam bengkelmu kau mengenali perayaan utama dan tujuannya, cara sambutan dahulu dan kini, serta amalan yang kekal sehingga hari ini.'),
(602, 'Pulang Beraya Bersama Nenek', 6, 'Masuki peranan seorang ibu moden yang membawa anak pulang beraya ke kampung. Bersama Nenek Dahulu, kau mengenali perayaan utama dan tujuannya, cara sambutan dahulu dan kini, serta amalan yang kekal.'),
(603, 'Kedai Seribu Perayaan', 6, 'Masuki peranan peniaga rumah kedai yang menjual kad, kuih dan hiasan untuk semua perayaan. Setiap pelanggan membawa cerita: perayaan utama, tujuan, cara sambutan dahulu dan kini, serta amalan yang kekal.');
INSERT INTO Scene (sceneID, sceneStoryline, sceneOrder, narrativeID, asset) VALUES
('e6_n1_s1', 'Bengkel kraf pada pagi sebelum perayaan. Kau, penggiat kraf, memegang gunting dan kertas berwarna sementara pelanggan dari pelbagai kaum berebut menempah hiasan untuk perayaan masing-masing.', 1, 601, 'petempatan_semua_kini.png'),
('e6_n1_s2', 'Papan tanda besar di tengah bengkel kraf yang berwarna-warni. Kau, penggiat kraf, mengumpulkan kad tujuan perayaan di atas meja kerja sambil pelanggan duduk menunggu.', 2, 601, 'tempat_beribadat_semua.png'),
('e6_n1_s3', 'Studio kedai gambar lama di sudut bengkel. Kau, penggiat kraf, menyusun bingkai dan kad ucapan sementara Nenek Dahulu dan murid saling bertukar cerita tentang cara dahulu dan kini.', 3, 601, 'mengambil_foto_dahulu.png'),
('e6_n1_s4', 'Laman rumah kayu dengan kolam putih di tanah. Kau, penggiat kraf, membongkok melukis corak sementara Kavitha, Ah Meng dan Mei Ling bergilir bercerita tentang cara dahulu dan kini.', 4, 601, 'kolam_deepavali_dahulu.png'),
('e6_n1_s5', 'Dapur kayu api di bawah bumbung yang berasap. Kau, penggiat kraf, membantu menyusun dulang kuih sementara Nenek Dahulu dan Aishah memasak secara gotong-royong.', 5, 601, 'penyediaan_kuih_muih_tradisional.png'),
('e6_n1_s6', 'Pentas pondok di tepi sawah padi pada petang yang keemasan. Kau, penggiat kraf, menggantung hiasan padi sementara Apai Jelani, Daniel dan Linda bercerita tentang Gawai dan Kaamatan.', 6, 601, 'unduk_ngadau_dahulu.png'),
('e6_n2_s1', 'Beranda rumah nenek di kampung pada petang sebelum raya. Kau, si ibu, baru turun dari kereta penuh bagasi dan jiran-jiran pelbagai kaum sudah berkumpul untuk bercerita tentang perayaan masing-masing.', 1, 602, 'petempatan_semua_dahulu.png'),
('e6_n2_s2', 'Laluan batu di hadapan rumah-rumah ibadat tidak jauh dari kampung. Kau, si ibu, berjalan dengan nenek dan anak sambil nenek mengira tujuan setiap perayaan dengan jari.', 2, 602, 'tempat_beribadat_berdekat.png'),
('e6_n2_s3', 'Ruang tamu bandar yang berkilau dengan lampu raya. Kau, si ibu, melambai di skrin televisyen yang menunjukkan nenek sedang tersenyum, sementara anak sibuk menaip ucapan di telefon.', 3, 602, 'suasana_dan_ucapan_raya_kini.png'),
('e6_n2_s4', 'Halaman rumah jiran yang meriah dengan kolam berwarna-warni. Kau, si ibu, mencangkung bersama Kavitha dan anak sambil Ah Meng dan Mei Ling menjemput kau ke meja makan besar Tahun Baharu Cina.', 4, 602, 'kolam_deepavali_sekarang.png'),
('e6_n2_s5', 'Kedai kuih raya yang sesak dengan pembeli. Kau, si ibu, menolak troli bersama nenek yang terpegun melihat balang kuih berderet, sementara anak berlari antara rak.', 5, 602, 'pembelian_kuih_muih_kini.png'),
('e6_n2_s6', 'Dewan perayaan Unduk Ngadau yang bergemerlapan di bandar. Kau, si ibu, duduk di antara penonton bersama nenek dan anak, sementara Apai Jelani dan Daniel datang bertamu dari Sarawak.', 6, 602, 'unduk_ngadau_sekarang.png'),
('e6_n3_s1', 'Kaunter kedai yang penuh dengan kad, hiasan dan kuih. Kau, si peniaga, membuka kedai pada pagi musim perayaan sementara pelanggan dari pelbagai kaum berbaris panjang di pintu.', 1, 603, 'bandar.png'),
('e6_n3_s2', 'Rak kad ucapan yang diatur mengikut tujuan perayaan. Kau, si peniaga, menyusun kad dengan label baharu sementara pelanggan membelek dan bertanya.', 2, 603, 'petempatan_semua_kini.png'),
('e6_n3_s3', 'Sudut kedai yang menyediakan bingkai gambar dan kad ucapan pelbagai gaya. Kau, si peniaga, menyusun kad lama dan telefon pintar di rak yang sama sementara Nenek Dahulu dan murid saling bertukar cerita.', 3, 603, 'mengambil_foto_kini.png'),
('e6_n3_s4', 'Ruang makan di tingkat atas kedai yang dihiasi lampion merah. Kau, si peniaga, menolong Ah Meng dan Kavitha menyusun hidangan dan hiasan kolam untuk pelanggan tetap.', 4, 603, 'makan_besar_cina_dahulu.png'),
('e6_n3_s5', 'Pojok kuih raya yang sesak dengan pembeli. Kau, si peniaga, menjaga kaunter sementara Nenek Dahulu dan Aishah membelek balang kuih sambil mengimbau cara lama.', 5, 603, 'pembelian_kuih_muih_kini.png'),
('e6_n3_s6', 'Jalan raya yang meriah dengan perarakan festival. Kau, si peniaga, menutup kedai sebentar dan melangkah ke luar menyaksikan perarakan bersama Apai Jelani, Daniel dan Linda.', 6, 603, 'festival_gawai_kini.png');
INSERT INTO Quest (questID, sceneID, questName, instruction, questType, description, questContent) VALUES
(601, 'e6_n1_s1', 'Misi Tempahan Semua Perayaan', 'Bantu murid memilih pernyataan yang betul tentang perayaan utama masyarakat di Malaysia.', '3', 'Mengenal pasti perayaan utama masyarakat di Malaysia.', '{"prompt": "Seorang murid menahan kau dan bertanya: yang manakah pernyataan yang betul tentang perayaan utama masyarakat di Malaysia?", "options": [{"text": "Hari Gawai, Pesta Kaamatan, Vaisakhi dan San Pedro juga termasuk perayaan utama masyarakat di Malaysia.", "isCorrect": true}, {"text": "Hanya Hari Raya, Tahun Baharu Cina dan Deepavali sahaja dikira perayaan utama masyarakat di Malaysia kini.", "isCorrect": false, "consequence": "Murid itu mencatat tiga perayaan sahaja. Linda, Harjit dan Pak Nelayan terkilan kerana perayaan mereka tidak disebut."}, {"text": "Krismas dan Thaipusam bukan perayaan utama; hanya Wesak dan Gawai yang termasuk dalam senarai itu.", "isCorrect": false, "consequence": "Murid itu menyingkirkan Krismas dan Thaipusam. Daniel dan Kavitha menggeleng kerana perayaan mereka disalah faham."}], "aftermath": "Senarai perayaan tidak lengkap. Murid-murid pulang dengan nota yang meninggalkan beberapa perayaan.", "turns": [{"after": 8, "options": [{"text": "Vaisakhi.", "isCorrect": true, "reaction": "Tepat, penggiat! Harjit mengangguk dan kain berwarna dilambai riang. Satu mata untuk kau!"}, {"text": "Hari Wesak.", "isCorrect": false, "reaction": "Itu perayaan Mei Ling, penggiat! Harjit tersenyum dan menunjuk ke arah Mei Ling."}, {"text": "Pesta Kaamatan.", "isCorrect": false, "reaction": "Itu perayaan Linda, penggiat! Harjit menggeleng sambil ketawa."}], "clue": "Harjit menyebut perayaannya sebaik sahaja menyebut kain berwarna."}]}'),
(602, 'e6_n1_s2', 'Padanan Pantas: Tujuan Perayaan', 'Padankan setiap tujuan dengan perayaan yang diraikan untuk tujuan itu.', '4', 'Mengenal pasti tujuan perayaan masyarakat di Malaysia.', '{"pairs": [{"text": "Keagamaan", "pair": 1}, {"text": "Aidilfitri, Aidiladha, Krismas dan Thaipusam", "pair": 1}, {"text": "Meraikan tahun baharu", "pair": 2}, {"text": "Tahun Baharu Cina, Tahon Baro, Jis Pai, Tahun Bahauk, Tawun Empai", "pair": 2}, {"text": "Mensyukuri hasil tanaman atau laut", "pair": 3}, {"text": "Hari Gawai, Pesta Kaamatan, Vaisakhi dan San Pedro", "pair": 3}, {"text": "Kebaikan mengatasi kejahatan", "pair": 4}, {"text": "Deepavali", "pair": 4}, {"text": "Mengingati tokoh agama", "pair": 5}, {"text": "Hari Wesak", "pair": 5}], "aftermath": "Tujuan perayaan tersalah padan. Pelanggan membawa pulang hiasan untuk perayaan yang salah.", "turns": [{"after": 6, "options": [{"text": "Mensyukuri hasil tanaman atau hasil laut.", "isCorrect": true, "reaction": "Tepat, penggiat! Murid itu menulis laju-laju dan Linda bertepuk tangan."}, {"text": "Meraikan tahun baharu secara bersama.", "isCorrect": false, "reaction": "Itu tujuan Tahun Baharu Cina dan seumpamanya, penggiat! Ah Meng menggeleng sambil ketawa."}, {"text": "Mengingati tokoh agama yang dihormati.", "isCorrect": false, "reaction": "Itu tujuan Hari Wesak, penggiat! Mei Ling tersenyum sambil menggeleng."}], "clue": "Gawai, Kaamatan, Vaisakhi dan San Pedro disambut kerana tanaman atau laut."}]}'),
(603, 'e6_n1_s3', 'Misi Kamera: Cara Dahulu', 'Cari bukti cara sambutan dahulu pada gambar studio kedai gambar.', '2', 'Mengenal pasti perbezaan kad ucapan dan foto keluarga dahulu dan kini.', '{"bgImage": "../assets/gameAsset/background/mengambil_foto_dahulu.png", "hotspots": [{"name": "Kamera lama: foto keluarga diambil di kedai gambar", "top": "45%", "left": "20%"}, {"name": "Latar lukisan studio kedai gambar untuk foto keluarga dahulu", "top": "40%", "left": "55%"}, {"name": "Kerusi untuk bergambar bersama keluarga di kedai gambar", "top": "70%", "left": "52%"}, {"name": "Lampu studio kedai gambar pada zaman dahulu", "top": "22%", "left": "94%"}], "aftermath": "Bukti cara dahulu tersalah cari. Murid menyangka cara dahulu dan kini sama sahaja.", "turns": [{"after": 4, "options": [{"text": "Mengambil foto keluarga di kedai gambar.", "isCorrect": true, "reaction": "Tepat, penggiat! Nenek Dahulu menepuk tangan dan kamera lama pun berbunyi klik!"}, {"text": "Swafoto dan memuat naiknya di media sosial.", "isCorrect": false, "reaction": "Itu cara kini, penggiat! Murid itu ketawa kerana jawapan itu tersasar zaman."}, {"text": "Menghantar ucapan menggunakan media sosial.", "isCorrect": false, "reaction": "Itu juga cara kini, penggiat! Nenek Dahulu menggeleng sambil tersenyum."}], "clue": "Studio dengan kamera tripod menunjukkan cara foto keluarga dahulu."}]}'),
(604, 'e6_n1_s4', 'Nyahkod Catatan Kolam Lama', 'Baca catatan lama dan tentukan bahan membuat kolam pada zaman dahulu.', '5', 'Mengenal pasti perbezaan kolam Deepavali dan makan besar Tahun Baharu Cina dahulu dan kini.', '{"clueText": "Catatan lama menulis: Pada Deepavali, orang membuat kolam di hadapan rumah. Bahan membuat kolam dahulu sudah luntur dan tidak kelihatan. Kini kolam dibuat daripada beras atau hampas kelapa berwarna-warni.", "options": [{"text": "Tepung.", "isCorrect": true}, {"text": "Beras berwarna-warni.", "isCorrect": false, "consequence": "Catatan itu dibaca dengan bahan kini. Pembaca menyangka kolam dahulu sama seperti kolam kini."}, {"text": "Hampas kelapa berwarna-warni.", "isCorrect": false, "consequence": "Catatan itu dibaca dengan bahan kini. Pembaca tidak lagi tahu bahawa kolam dahulu daripada tepung."}], "aftermath": "Catatan kolam disalah baca. Cara dahulu dan kini bercampur dalam ingatan kau.", "turns": [{"after": 5, "options": [{"text": "Tepung.", "isCorrect": true, "reaction": "Tepat, penggiat! Kavitha bersorak dan corak putih pun nampak bercahaya."}, {"text": "Beras berwarna-warni.", "isCorrect": false, "reaction": "Itu bahan kolam kini, penggiat! Kavitha tersenyum dan menggeleng."}, {"text": "Hampas kelapa berwarna-warni.", "isCorrect": false, "reaction": "Itu juga bahan kolam kini, penggiat! Kavitha ketawa kecil."}], "clue": "Catatan lama menyebut kolam dibuat daripada bahan putih, sebelum beras berwarna wujud."}]}'),
(605, 'e6_n1_s5', 'Soalan Sergahan di Dapur', 'Bantu murid memilih amalan perayaan yang masih kekal sehingga kini.', '3', 'Mengenal pasti perbezaan penyediaan kuih-muih dahulu dan kini serta amalan yang kekal.', '{"prompt": "Seorang murid menahan kau di dapur dan bertanya: yang manakah amalan perayaan yang kekal dahulu dan kini?", "options": [{"text": "Tradisi balik ke kampung, pemberian duit raya dan amalan kunjung-mengunjung.", "isCorrect": true}, {"text": "Menghantar kad ucapan melalui pos dan mengambil foto keluarga di kedai gambar.", "isCorrect": false, "consequence": "Murid itu menyangka cara dahulu masih kekal. Nenek Dahulu menggeleng kerana kini ramai menghantar ucapan secara elektronik."}, {"text": "Menyediakan kuih-muih secara gotong-royong menggunakan bahan dan kaedah tradisional sahaja.", "isCorrect": false, "consequence": "Murid itu menyangka cara kuih dahulu tidak berubah. Aishah menunjuk peralatan moden dan kuih raya yang mudah dibeli."}], "aftermath": "Amalan yang kekal disalah faham. Murid menyangka semua cara beraya tidak pernah berubah.", "turns": [{"after": 4, "options": [{"text": "Balik ke kampung, duit raya dan kunjung-mengunjung.", "isCorrect": true, "reaction": "Tepat, penggiat! Nenek Dahulu tersenyum bangga dan Aishah bertepuk tangan."}, {"text": "Menghantar kad ucapan melalui pos dan bergambar di kedai gambar.", "isCorrect": false, "reaction": "Itu cara dahulu yang sudah berubah, penggiat! Nenek Dahulu menggeleng sambil ketawa."}, {"text": "Menyediakan kuih secara gotong-royong dengan kaedah tradisional sahaja.", "isCorrect": false, "reaction": "Cara itu sudah banyak berubah, penggiat! Aishah menunjuk ke arah peralatan moden."}], "clue": "Tiga amalan yang tidak berubah: balik kampung, duit raya dan kunjung-mengunjung."}]}'),
(606, 'e6_n1_s6', 'Misi Pentas: Unduk Ngadau Dahulu', 'Cari bukti Unduk Ngadau dahulu dan hasil tanaman yang disyukuri pada gambar.', '2', 'Mengenal pasti perbezaan Hari Gawai dan Pesta Kaamatan (Unduk Ngadau) dahulu dan kini.', '{"bgImage": "../assets/gameAsset/background/unduk_ngadau_dahulu.png", "hotspots": [{"name": "Pemenang Unduk Ngadau dahulu: dipilih berdasarkan semangat Huminodun", "top": "45%", "left": "68%"}, {"name": "Tiga peserta Unduk Ngadau menunggu keputusan di tepi pentas", "top": "55%", "left": "38%"}, {"name": "Pentas pondok Pesta Kaamatan di tepi sawah", "top": "40%", "left": "60%"}, {"name": "Sawah padi: hasil tanaman yang disyukuri semasa Kaamatan dan Gawai", "top": "60%", "left": "8%"}], "aftermath": "Bukti Unduk Ngadau tersalah cari. Cara memilih pemenang dahulu dan kini bercampur.", "turns": [{"after": 5, "options": [{"text": "Pemenang dipilih berdasarkan semangat Huminodun.", "isCorrect": true, "reaction": "Tepat, penggiat! Linda bertepuk tangan dan padi pun beralun gembira."}, {"text": "Pemenang dipilih melalui sesi soal jawab sejarah sahaja.", "isCorrect": false, "reaction": "Itu cara kini, penggiat! Linda menggeleng sambil tersenyum."}, {"text": "Pemenang dipilih daripada golongan petani sahaja.", "isCorrect": false, "reaction": "Itu bukan cara memilih pemenang Unduk Ngadau, penggiat! Apai Jelani ketawa."}], "clue": "Dahulu pemenang dipilih kerana semangat Huminodun, bukan kerana soal jawab."}]}'),
(607, 'e6_n2_s1', 'Padanan Kumpulan Perayaan', 'Padankan setiap kumpulan dengan perayaan yang tergolong di dalamnya.', '4', 'Mengenal pasti perayaan utama masyarakat di Malaysia.', '{"pairs": [{"text": "Dua Hari Raya", "pair": 1}, {"text": "Hari Raya Aidilfitri dan Hari Raya Aidiladha", "pair": 1}, {"text": "Perayaan Hindu dan Sikh", "pair": 2}, {"text": "Deepavali, Thaipusam dan Vaisakhi", "pair": 2}, {"text": "Perayaan Kristian dan Buddha", "pair": 3}, {"text": "Krismas dan Hari Wesak", "pair": 3}, {"text": "Perayaan Sabah dan Sarawak", "pair": 4}, {"text": "Pesta Kaamatan dan Hari Gawai", "pair": 4}, {"text": "Perayaan lain dalam senarai", "pair": 5}, {"text": "Tahun Baharu Cina, Genggulang, Hari Moyang dan San Pedro", "pair": 5}], "aftermath": "Perayaan tersalah kumpulan. Kerja rumah murid dipenuhi dengan pengkelasan yang silap.", "turns": [{"after": 7, "options": [{"text": "Sabah.", "isCorrect": true, "reaction": "Tepat, Ibu! Linda bersorak dan menunjukkan hiasan padi miliknya."}, {"text": "Sarawak.", "isCorrect": false, "reaction": "Hari Gawai di Sarawak, Ibu! Pesta Kaamatan di Sabah. Daniel menyampuk sambil ketawa."}, {"text": "Melaka.", "isCorrect": false, "reaction": "Bukan Melaka, Ibu! Linda menggeleng-geleng sambil tersenyum lebar."}], "clue": "Linda ialah Kadazandusun dari negeri Borneo yang bukan Sarawak."}]}'),
(608, 'e6_n2_s2', 'Nyahkod Surat Lama Nenek', 'Baca surat lama yang luntur dan tentukan tujuan perayaan Deepavali.', '5', 'Mengenal pasti tujuan perayaan masyarakat di Malaysia.', '{"clueText": "Surat lama menulis: Keagamaan untuk Aidilfitri, Aidiladha, Krismas dan Thaipusam. Hari Wesak untuk mengingati tokoh agama. Tujuan Deepavali sudah luntur dan tidak kelihatan, tetapi ia berkait dengan cahaya mengatasi kegelapan.", "options": [{"text": "Unsur baik mengatasi kejahatan.", "isCorrect": true}, {"text": "Mensyukuri hasil tanaman atau hasil laut.", "isCorrect": false, "consequence": "Surat itu disalah baca. Anak-anak menyangka Deepavali ialah perayaan hasil tuaian, bukan kebaikan mengatasi kejahatan."}, {"text": "Meraikan tahun baharu.", "isCorrect": false, "consequence": "Surat itu disalah baca. Anak-anak menyangka Deepavali ialah tahun baharu, lalu catatan mereka tersasar."}], "aftermath": "Tujuan perayaan disalah faham. Anak-anak pulang dengan catatan yang tersasar daripada tujuan sebenar.", "turns": [{"after": 6, "options": [{"text": "Unsur baik mengatasi kejahatan.", "isCorrect": true, "reaction": "Tepat, Ibu! Nenek menepuk lutut dan surat lama bercahaya semula."}, {"text": "Mensyukuri hasil tanaman atau hasil laut.", "isCorrect": false, "reaction": "Itu tujuan Gawai, Kaamatan, Vaisakhi dan San Pedro, Ibu! Nenek menggeleng sambil tersenyum."}, {"text": "Mengingati tokoh agama.", "isCorrect": false, "reaction": "Itu tujuan Hari Wesak, Ibu! Murid itu ketawa."}], "clue": "Surat lama menyebut cahaya dan kegelapan, kebaikan dan kejahatan."}]}'),
(609, 'e6_n2_s3', 'Soalan Sergahan di Ruang Tamu', 'Bantu murid memilih pernyataan yang betul tentang kad ucapan dan foto keluarga dahulu dan kini.', '3', 'Mengenal pasti perbezaan kad ucapan dan foto keluarga dahulu dan kini.', '{"prompt": "Murid itu menunjuk skrin dan bertanya: yang manakah perbezaan kad ucapan dan foto keluarga dahulu dan kini?", "options": [{"text": "Dahulu kad dihantar melalui pos dan foto di kedai gambar; kini ucapan melalui media sosial dan swafoto.", "isCorrect": true}, {"text": "Dahulu ucapan melalui media sosial dan swafoto; kini kad melalui pos dan foto di kedai gambar.", "isCorrect": false, "consequence": "Murid itu menukar zaman. Nenek tergelak kerana pos tidak wujud pada zaman media sosial."}, {"text": "Dahulu dan kini sama sahaja tanpa perubahan; kad dihantar melalui pos dan foto di kedai gambar sahaja.", "isCorrect": false, "consequence": "Murid itu menyangka tiada perubahan. Nenek menunjuk telefon yang berbunyi PING sebagai bukti perubahan."}], "aftermath": "Cara ucapan dan foto dahulu dan kini tertukar. Murid menulis perbezaan yang silap dalam buku.", "turns": [{"after": 4, "options": [{"text": "Menggunakan media elektronik dan media sosial.", "isCorrect": true, "reaction": "Tepat, Ibu! Murid itu bersorak dan telefon berbunyi PING seolah-olah bersetuju."}, {"text": "Melalui pos atau serahan tangan di kampung.", "isCorrect": false, "reaction": "Itu cara dahulu, Ibu! Nenek mengangkat kad lama sambil ketawa."}, {"text": "Mengambil foto di kedai gambar yang lama itu.", "isCorrect": false, "reaction": "Itu cara dahulu untuk foto, Ibu, bukan untuk ucapan! Nenek tersenyum."}], "clue": "Ucapan kini dihantar dengan peranti yang dipegang murid itu."}]}'),
(610, 'e6_n2_s4', 'Misi Halaman: Kolam Kini', 'Cari bukti kolam kini dan meja makan besar pada gambar halaman.', '2', 'Mengenal pasti perbezaan kolam Deepavali dan makan besar Tahun Baharu Cina dahulu dan kini.', '{"bgImage": "../assets/gameAsset/background/kolam_deepavali_sekarang.png", "hotspots": [{"name": "Kolam kini daripada beras atau hampas kelapa berwarna-warni", "top": "65%", "left": "50%"}, {"name": "Kanak-kanak melukis kolam bersama keluarga", "top": "62%", "left": "82%"}, {"name": "Keluarga duduk bersama membuat kolam pada Deepavali", "top": "40%", "left": "32%"}, {"name": "Pelita di sisi kolam semasa Deepavali", "top": "80%", "left": "42%"}], "aftermath": "Bukti kolam kini tersalah cari. Cara dahulu dan kini bercampur dalam ingatan.", "turns": [{"after": 4, "options": [{"text": "Kolam daripada beras atau hampas kelapa berwarna-warni.", "isCorrect": true, "reaction": "Tepat, Puan! Kavitha menepuk tangan dan manik-manik pelangi bergemerlapan."}, {"text": "Kolam daripada tepung putih sahaja tanpa warna lain.", "isCorrect": false, "reaction": "Itu bahan kolam dahulu, Puan! Kavitha ketawa kecil."}, {"text": "Kolam dibuat di kedai gambar lama itu bersama kamera.", "isCorrect": false, "reaction": "Itu bukan tempat membuat kolam, Puan! Ah Meng ketawa terbahak-bahak."}], "clue": "Kolam kini berwarna-warni kerana bahan baharu, bukan tepung putih."}]}'),
(611, 'e6_n2_s5', 'Susun Urutan Kuih dan Amalan', 'Susun cara menyediakan kuih dahulu, kini dan amalan yang kekal mengikut urutan.', '1', 'Mengenal pasti perbezaan penyediaan kuih-muih dahulu dan kini serta amalan yang kekal.', '{"timelineItems": [{"id": 1, "year": "Dahulu", "text": "Kuih-muih disediakan menggunakan bahan dan kaedah tradisional secara gotong-royong", "why": "Jiran dan keluarga berkumpul membantu."}, {"id": 2, "year": "Kini", "text": "Peralatan moden memudahkan penyediaan dan kuih raya juga mudah dibeli", "why": "Kemudahan menjimatkan masa."}, {"id": 3, "year": "Sentiasa kekal", "text": "Tradisi balik ke kampung, pemberian duit raya dan kunjung-mengunjung", "why": "Amalan ini tidak berubah walaupun zaman berubah."}], "aftermath": "Urutan cara dahulu dan kini tersusun salah. Anak-anak menyangka zaman berubah tanpa amalan yang kekal.", "turns": [{"after": 4, "options": [{"text": "Dahulu, kini, kemudian yang kekal.", "isCorrect": true, "reaction": "Tepat, Ibu! Nenek mengangguk dan troli pun seolah-olah bergerak laju."}, {"text": "Kini, dahulu, kemudian yang kekal.", "isCorrect": false, "reaction": "Tertukar, Ibu! Nenek ketawa kerana dahulu datang sebelum kini."}, {"text": "Yang kekal dahulu, kemudian kini, dahulu.", "isCorrect": false, "reaction": "Bercampur-campur, Ibu! Murid itu menggaru kepala."}], "clue": "Dahulu bermula dengan tradisi, kini dengan kemudahan, dan yang kekal tidak berubah sepanjang masa."}]}'),
(612, 'e6_n2_s6', 'Nyahkod Pengumuman Unduk Ngadau', 'Baca pengumuman yang luntur dan tentukan satu lagi asas pemilihan pemenang Unduk Ngadau kini.', '5', 'Mengenal pasti perbezaan Hari Gawai dan Pesta Kaamatan (Unduk Ngadau) dahulu dan kini.', '{"clueText": "Pengumuman menulis: Pemenang Unduk Ngadau dipilih berdasarkan semangat Huminodun, iaitu kesanggupan berkorban demi menyelamatkan generasi. Satu lagi asas pemilihan kini sudah luntur dan tidak kelihatan, tetapi berkait dengan sesi soal jawab.", "options": [{"text": "Sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau.", "isCorrect": true}, {"text": "Upacara ritual oleh golongan petani daripada kaum Dayak.", "isCorrect": false, "consequence": "Pengumuman itu dibaca dengan Hari Gawai dahulu. Penonton menyangka Unduk Ngadau kini sama seperti upacara Gawai dahulu."}, {"text": "Pertandingan menanam padi paling cepat di sawah.", "isCorrect": false, "consequence": "Pengumuman itu ditambah dengan cabaran yang tiada. Penonton keliru tentang cara memilih pemenang sebenar."}], "aftermath": "Pengumuman Unduk Ngadau disalah baca. Cara memilih pemenang dahulu dan kini bercampur.", "turns": [{"after": 4, "options": [{"text": "Sesi soal jawab sejarah dan kehidupan lampau.", "isCorrect": true, "reaction": "Tepat, Puan! Linda bersorak dan semua penonton bertepuk tangan."}, {"text": "Pertandingan menanam padi paling cepat.", "isCorrect": false, "reaction": "Bukan, Puan! Linda ketawa kerana tiada pertandingan itu dalam Unduk Ngadau kini."}, {"text": "Upacara ritual oleh petani kaum Dayak sahaja.", "isCorrect": false, "reaction": "Itu Hari Gawai dahulu, Puan! Apai Jelani menggeleng sambil tersenyum."}], "clue": "Pengumuman menyebut semangat Huminodun dan satu lagi sesi yang berkait dengan sejarah."}]}'),
(613, 'e6_n3_s1', 'Nyahkod Senarai Jualan Kedai', 'Baca senarai jualan yang luntur dan lengkapkan nama perayaan yang tidak kelihatan.', '5', 'Mengenal pasti perayaan utama masyarakat di Malaysia.', '{"clueText": "Senarai jualan kedai menulis: Hari Raya Aidilfitri, Hari Raya Aidiladha, Tahun Baharu Cina, Deepavali, Krismas dan Hari Wesak dengan jelas. Baki perayaan sudah luntur dan tidak kelihatan.", "options": [{"text": "Thaipusam, Gawai, Kaamatan, Vaisakhi, Tahun Baharu, Genggulang, Hari Moyang dan San Pedro.", "isCorrect": true}, {"text": "Thaipusam, Hari Gawai, Pesta Kaamatan dan Vaisakhi sahaja, tanpa tahun baharu dan San Pedro.", "isCorrect": false, "consequence": "Senarai ditulis semula dengan separuh perayaan sahaja. Pelanggan yang menyambut San Pedro dan Hari Moyang pulang hampa."}, {"text": "Hanya Hari Gawai dan Pesta Kaamatan sahaja, tanpa Thaipusam, Vaisakhi dan San Pedro.", "isCorrect": false, "consequence": "Senarai ditulis semula dengan dua perayaan sahaja. Kavitha dan Harjit pulang tanpa hiasan perayaan mereka."}], "aftermath": "Senarai perayaan di kedai tidak lengkap. Pelanggan pulang tanpa barang perayaan mereka.", "turns": [{"after": 6, "options": [{"text": "Thaipusam, Gawai, Kaamatan, Vaisakhi, Tahun Baharu, Genggulang, Hari Moyang dan San Pedro.", "isCorrect": true, "reaction": "Tepat, tauke! Murid itu bersorak dan senarai jualan pun terang semula!"}, {"text": "Thaipusam, Hari Gawai, Pesta Kaamatan dan Vaisakhi sahaja, tanpa tahun baharu dan San Pedro.", "isCorrect": false, "reaction": "Ada yang tertinggal, tauke! Pak Nelayan melambai-lambai kerana San Pedro tidak disebut."}, {"text": "Hanya Hari Gawai dan Pesta Kaamatan, tanpa Thaipusam, Vaisakhi dan San Pedro.", "isCorrect": false, "reaction": "Banyak tertinggal, tauke! Kavitha dan Harjit saling berpandangan kerana perayaan mereka tidak disebut."}], "clue": "Senarai itu menyebut enam perayaan yang jelas. Baki perayaan ialah Thaipusam hingga San Pedro."}]}'),
(614, 'e6_n3_s2', 'Soalan Sergahan di Kaunter', 'Bantu murid memilih tujuan perayaan yang betul.', '3', 'Mengenal pasti tujuan perayaan masyarakat di Malaysia.', '{"prompt": "Murid itu bertanya di kaunter: yang manakah padanan tujuan dan perayaan yang betul?", "options": [{"text": "Mensyukuri hasil: Gawai, Kaamatan, Vaisakhi, San Pedro. Kebaikan mengatasi kejahatan: Deepavali.", "isCorrect": true}, {"text": "Mensyukuri hasil: Deepavali dan Krismas. Kebaikan mengatasi kejahatan: Gawai, Kaamatan, Vaisakhi dan San Pedro.", "isCorrect": false, "consequence": "Murid itu menukar tujuan perayaan. Pelanggan Deepavali menggeleng kerana tujuan perayaan mereka tersalah."}, {"text": "Mengingati tokoh agama: Aidilfitri dan Aidiladha. Meraikan tahun baharu: Hari Wesak dan Thaipusam.", "isCorrect": false, "consequence": "Murid itu mencampur tujuan dan perayaan. Mei Ling menggeleng kerana Wesak sepatutnya untuk mengingati tokoh agama."}], "aftermath": "Tujuan perayaan tersalah padan. Pelanggan membeli kad yang tidak sesuai dengan perayaan mereka.", "turns": [{"after": 5, "options": [{"text": "Mensyukuri hasil tanaman atau hasil laut.", "isCorrect": true, "reaction": "Tepat, tauke! Murid itu menekan loceng kaunter dengan gembira."}, {"text": "Meraikan tahun baharu secara bersama.", "isCorrect": false, "reaction": "Itu tujuan Tahun Baharu Cina dan seumpamanya, tauke! Ah Meng ketawa dari belakang."}, {"text": "Mengingati tokoh agama yang dihormati.", "isCorrect": false, "reaction": "Itu tujuan Hari Wesak, tauke! Mei Ling tersenyum sambil menggeleng."}], "clue": "Gawai dan Kaamatan menyambut padi, San Pedro menyambut hasil laut, jadi tujuannya sama."}]}'),
(615, 'e6_n3_s3', 'Susun Garis Masa Ucapan dan Foto', 'Susun cara kad ucapan dan foto keluarga dari zaman dahulu hingga kini.', '1', 'Mengenal pasti perbezaan kad ucapan dan foto keluarga dahulu dan kini.', '{"timelineItems": [{"id": 1, "year": "Dahulu", "text": "Kad ucapan dihantar melalui pos atau serahan tangan dan foto keluarga diambil di kedai gambar", "why": "Cara ini bergantung pada kad dan kedai gambar."}, {"id": 2, "year": "Kini", "text": "Ucapan dihantar menggunakan media elektronik dan media sosial, dan swafoto bersama keluarga dimuat naik di media sosial", "why": "Peranti dan media sosial menggantikan kad pos dan kedai gambar."}], "aftermath": "Cara dahulu dan kini tersusun terbalik. Murid menyangka media sosial wujud sebelum kad pos.", "turns": [{"after": 4, "options": [{"text": "Kad pos dahulu, media sosial kemudian.", "isCorrect": true, "reaction": "Tepat, tauke! Nenek tersenyum dan murid itu menunjukkan telefonnya dengan bangga."}, {"text": "Media sosial dahulu, kad pos kemudian.", "isCorrect": false, "reaction": "Terbalik, tauke! Nenek ketawa dan menunjuk kad lama di rak."}, {"text": "Kad pos dan media sosial serentak.", "isCorrect": false, "reaction": "Tidak serentak, tauke! Nenek menggeleng sambil mengira dengan jari."}], "clue": "Dahulu datang sebelum kini, dan kad pos wujud sebelum media sosial."}]}'),
(616, 'e6_n3_s4', 'Padanan Pantas: Kolam dan Makan Besar', 'Padankan kolam dan makan besar dahulu dan kini dengan bahan atau tempatnya.', '4', 'Mengenal pasti perbezaan kolam Deepavali dan makan besar Tahun Baharu Cina dahulu dan kini.', '{"pairs": [{"text": "Kolam Deepavali dahulu", "pair": 1}, {"text": "Tepung", "pair": 1}, {"text": "Kolam Deepavali kini", "pair": 2}, {"text": "Beras atau hampas kelapa berwarna-warni", "pair": 2}, {"text": "Makan besar Tahun Baharu Cina dahulu", "pair": 3}, {"text": "Di rumah bersama keluarga", "pair": 3}, {"text": "Makan besar Tahun Baharu Cina kini", "pair": 4}, {"text": "Di rumah, ada yang di restoran atau hotel", "pair": 4}], "aftermath": "Kolam dan makan besar tersalah padan. Pelanggan pulang dengan bahan dan tempat yang tidak sesuai.", "turns": [{"after": 4, "options": [{"text": "Kolam dahulu: tepung. Makan besar dahulu: di rumah.", "isCorrect": true, "reaction": "Tepat, tauke! Ah Meng dan Kavitha bertepuk tangan serentak."}, {"text": "Kolam dahulu: hampas kelapa. Makan besar dahulu: di hotel.", "isCorrect": false, "reaction": "Itu cara kini, tauke! Ah Meng menggeleng sambil ketawa."}, {"text": "Kolam dahulu: beras. Makan besar dahulu: di restoran.", "isCorrect": false, "reaction": "Itu juga cara kini, tauke! Kavitha tersenyum dan menggeleng."}], "clue": "Dahulu kolam daripada tepung dan makan besar di rumah. Kini bahan dan tempat lebih pelbagai."}]}'),
(617, 'e6_n3_s5', 'Misi Kedai: Bukti Kuih Kini', 'Cari bukti kuih raya kini yang mudah dibeli pada gambar pojok kuih.', '2', 'Mengenal pasti perbezaan penyediaan kuih-muih dahulu dan kini serta amalan yang kekal.', '{"bgImage": "../assets/gameAsset/background/pembelian_kuih_muih_kini.png", "hotspots": [{"name": "Rak balang kuih raya: kuih raya mudah dibeli di kedai", "top": "42%", "left": "40%"}, {"name": "Juruwang kedai: kuih kini dibeli dengan mudah", "top": "40%", "left": "82%"}, {"name": "Beg hadiah kuih raya yang siap dibungkus", "top": "80%", "left": "10%"}, {"name": "Papan Selamat Hari Raya di atas rak kuih", "top": "8%", "left": "52%"}], "aftermath": "Bukti kuih kini tersalah cari. Cara menyediakan kuih dahulu dan kini bercampur.", "turns": [{"after": 4, "options": [{"text": "Balang kuih raya yang siap dibeli di kedai.", "isCorrect": true, "reaction": "Tepat, tauke! Nenek Dahulu tersenyum dan murid itu terus ke kaunter."}, {"text": "Dapur kayu api untuk menggoreng kuih bersama jiran.", "isCorrect": false, "reaction": "Itu cara dahulu, tauke! Nenek Dahulu ketawa sambil mengimbau kenangan."}, {"text": "Kad ucapan yang dihantar melalui pos.", "isCorrect": false, "reaction": "Itu bukan tentang kuih, tauke! Aishah menunjuk ke arah balang kuih."}], "clue": "Kuih kini boleh dibeli terus di kedai dan tidak perlu disediakan sendiri."}]}'),
(618, 'e6_n3_s6', 'Padanan Pantas: Gawai dan Unduk Ngadau', 'Padankan Hari Gawai dan Unduk Ngadau dahulu dan kini dengan cara sambutan atau pemilihan pemenangnya.', '4', 'Mengenal pasti perbezaan Hari Gawai dan Pesta Kaamatan (Unduk Ngadau) dahulu dan kini.', '{"pairs": [{"text": "Hari Gawai dahulu", "pair": 1}, {"text": "Petani kaum Dayak dengan upacara ritual", "pair": 1}, {"text": "Hari Gawai kini", "pair": 2}, {"text": "Pelbagai kaum tanpa mengira bidang pekerjaan", "pair": 2}, {"text": "Unduk Ngadau dahulu", "pair": 3}, {"text": "Semangat Huminodun, berkorban demi menyelamatkan generasi", "pair": 3}, {"text": "Unduk Ngadau kini", "pair": 4}, {"text": "Juga sesi soal jawab sejarah dan kehidupan lampau", "pair": 4}], "aftermath": "Cara sambutan dan pemilihan pemenang tersalah padan. Perarakan terhenti dan penonton kebingungan.", "turns": [{"after": 4, "options": [{"text": "Gawai kini: pelbagai kaum tanpa mengira pekerjaan.", "isCorrect": true, "reaction": "Tepat, tauke! Apai Jelani bersorak dan penari berarak lebih laju."}, {"text": "Gawai kini: petani kaum Dayak sahaja.", "isCorrect": false, "reaction": "Itu cara dahulu, tauke! Daniel menggeleng sambil tersenyum."}, {"text": "Gawai kini: sesi soal jawab sejarah sahaja.", "isCorrect": false, "reaction": "Itu bukan tentang Gawai, tauke! Linda ketawa sambil menggeleng."}], "clue": "Kini Gawai disambut oleh ramai kaum, bukan hanya oleh petani Dayak."}]}');
INSERT INTO LearningSupport (questID, sceneID, supportType, hint, explanation, feedback) VALUES
(NULL, 'e6_n1_s1', 'hint', 'Perayaan utama: Aidilfitri, Aidiladha, Tahun Baharu Cina, Deepavali, Krismas, Wesak, Thaipusam, Gawai, Kaamatan, Vaisakhi, Genggulang, Hari Moyang, San Pedro.', NULL, NULL),
(601, NULL, 'hint', 'Ingat perayaan Gawai, Kaamatan, Vaisakhi dan San Pedro juga termasuk, bukan hanya tiga perayaan besar.', 'Perayaan utama: Hari Raya Aidilfitri, Hari Raya Aidiladha, Tahun Baharu Cina, Deepavali, Krismas, Hari Wesak, Thaipusam, Hari Gawai, Pesta Kaamatan, Vaisakhi, Sambutan Tahun Baharu, Genggulang, Hari Moyang dan San Pedro.', 'Betul! Bengkel bergema dengan tepukan dan semua pelanggan melambai gembira.'),
(NULL, 'e6_n1_s2', 'hint', 'Tujuan: keagamaan, meraikan tahun baharu, mensyukuri hasil tanaman atau laut, kebaikan mengatasi kejahatan, dan mengingati tokoh agama.', NULL, NULL),
(602, NULL, 'hint', 'Lima tujuan: keagamaan, tahun baharu, syukur hasil, kebaikan atasi kejahatan dan mengingati tokoh.', 'Tujuan perayaan: keagamaan (Aidilfitri, Aidiladha, Krismas, Thaipusam); meraikan tahun baharu (Tahun Baharu Cina, Tahon Baro, Jis Pai, Tahun Bahauk, Tawun Empai); mensyukuri hasil (Gawai, Kaamatan, Vaisakhi, San Pedro); kebaikan mengatasi kejahatan (Deepavali); mengingati tokoh agama (Wesak).', 'Betul! Lima kad bertemu pasangannya dan murid bersorak.'),
(NULL, 'e6_n1_s3', 'hint', 'Dahulu: kad ucapan melalui pos atau serahan tangan, foto di kedai gambar. Kini: ucapan melalui media elektronik dan media sosial, swafoto.', NULL, NULL),
(603, NULL, 'hint', 'Cari kamera lama, latar lukisan, kerusi dan lampu studio. Semuanya cara dahulu di kedai gambar.', 'Kad ucapan: dahulu dihantar melalui pos atau serahan tangan; kini dihantar menggunakan media elektronik dan media sosial. Foto keluarga: dahulu di kedai gambar; kini swafoto dan dimuat naik di media sosial.', 'Hebat! Empat bukti ditemui dan studio lama pun seperti hidup semula.'),
(NULL, 'e6_n1_s4', 'hint', 'Kolam Deepavali: dahulu tepung, kini beras atau hampas kelapa berwarna-warni. Makan besar Tahun Baharu Cina: dahulu di rumah, kini ada yang di restoran atau hotel.', NULL, NULL),
(604, NULL, 'hint', 'Dahulu tepung, kini beras atau hampas kelapa berwarna-warni. Makan besar dahulu di rumah.', 'Kolam Deepavali: dahulu daripada tepung; kini daripada beras atau hampas kelapa berwarna-warni. Makan besar Tahun Baharu Cina: dahulu di rumah bersama keluarga; kini di rumah, ada yang memilih restoran atau hotel.', 'Betul! Catatan lama itu terang semula dan Kavitha tersenyum puas.'),
(NULL, 'e6_n1_s5', 'hint', 'Kuih dahulu: bahan dan kaedah tradisional, gotong-royong. Kini: peralatan moden, kuih raya mudah dibeli. Kekal: balik kampung, duit raya, kunjung-mengunjung.', NULL, NULL),
(605, NULL, 'hint', 'Yang kekal: balik kampung, duit raya, kunjung-mengunjung. Kuih dan kad sudah berubah.', 'Kuih-muih: dahulu bahan dan kaedah tradisional secara gotong-royong; kini peralatan moden dan kuih raya mudah dibeli. Amalan kekal: balik ke kampung, pemberian duit raya, kunjung-mengunjung.', 'Betul! Dapur berasap itu bergema dengan tepukan gembira.'),
(NULL, 'e6_n1_s6', 'hint', 'Gawai: dahulu petani Dayak dengan upacara ritual, kini pelbagai kaum. Unduk Ngadau: dahulu semangat Huminodun, kini juga sesi soal jawab.', NULL, NULL),
(606, NULL, 'hint', 'Cari pemenang bermahkota, tiga peserta, pentas pondok dan sawah padi. Ingat semangat Huminodun.', 'Hari Gawai: dahulu diraikan petani kaum Dayak dengan upacara ritual; kini oleh pelbagai kaum tanpa mengira pekerjaan. Unduk Ngadau (Pesta Kaamatan): dahulu pemenang dipilih berdasarkan semangat Huminodun (kesanggupan berkorban demi menyelamatkan generasi); kini juga berdasarkan sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau.', 'Hebat! Semua bukti ditemui dan pentas pondok bergema dengan sorakan.'),
(NULL, 'e6_n2_s1', 'hint', 'Kumpulan perayaan: dua Hari Raya, Hindu dan Sikh, Kristian dan Buddha, Sabah dan Sarawak, serta perayaan lain dalam senarai.', NULL, NULL),
(607, NULL, 'hint', 'Dua Hari Raya, Hindu dan Sikh, Kristian dan Buddha, Sabah dan Sarawak, serta lain-lain.', 'Perayaan utama: Hari Raya Aidilfitri, Hari Raya Aidiladha, Tahun Baharu Cina, Deepavali, Krismas, Hari Wesak, Thaipusam, Hari Gawai, Pesta Kaamatan, Vaisakhi, Sambutan Tahun Baharu, Genggulang, Hari Moyang dan San Pedro.', 'Betul! Senarai kerja rumah murid penuh dan nenek bertepuk tangan.'),
(NULL, 'e6_n2_s2', 'hint', 'Tujuan perayaan: keagamaan, meraikan tahun baharu, mensyukuri hasil, kebaikan atasi kejahatan, mengingati tokoh agama.', NULL, NULL),
(608, NULL, 'hint', 'Deepavali: unsur baik mengatasi kejahatan. Wesak: tokoh agama. Gawai, Kaamatan: syukur hasil.', 'Tujuan perayaan: keagamaan (Aidilfitri, Aidiladha, Krismas, Thaipusam); meraikan tahun baharu (Tahun Baharu Cina, Tahon Baro, Jis Pai, Tahun Bahauk, Tawun Empai); mensyukuri hasil (Gawai, Kaamatan, Vaisakhi, San Pedro); kebaikan mengatasi kejahatan (Deepavali); mengingati tokoh agama (Wesak).', 'Betul! Surat lama terang semula dan nenek tersenyum puas.'),
(NULL, 'e6_n2_s3', 'hint', 'Kad ucapan: dahulu pos atau serahan tangan, kini media elektronik dan sosial. Foto keluarga: dahulu kedai gambar, kini swafoto dan media sosial.', NULL, NULL),
(609, NULL, 'hint', 'Dahulu pos dan kedai gambar. Kini media elektronik, media sosial dan swafoto.', 'Kad ucapan: dahulu dihantar melalui pos atau serahan tangan; kini melalui media elektronik dan media sosial. Foto keluarga: dahulu di kedai gambar; kini swafoto dan dimuat naik di media sosial.', 'Betul! Telefon berbunyi PING dan nenek ketawa bangga.'),
(NULL, 'e6_n2_s4', 'hint', 'Kolam kini: beras atau hampas kelapa berwarna-warni (dahulu tepung). Makan besar: dahulu di rumah, kini ada yang di restoran atau hotel.', NULL, NULL),
(610, NULL, 'hint', 'Cari kolam berwarna-warni, kanak-kanak, keluarga dan pelita. Makan besar dahulu di rumah.', 'Kolam Deepavali: dahulu daripada tepung; kini daripada beras atau hampas kelapa berwarna-warni. Makan besar Tahun Baharu Cina: dahulu di rumah bersama keluarga; kini di rumah, ada yang memilih restoran atau hotel.', 'Hebat! Halaman berkilau dan semua jiran bersorak.'),
(NULL, 'e6_n2_s5', 'hint', 'Susun: dahulu (gotong-royong, tradisional), kini (peralatan moden, mudah dibeli), dan amalan kekal (balik kampung, duit raya, kunjung-mengunjung).', NULL, NULL),
(611, NULL, 'hint', 'Dahulu gotong-royong tradisional, kini moden dan mudah dibeli, sentiasa kekal balik kampung dan duit raya.', 'Kuih-muih: dahulu bahan dan kaedah tradisional secara gotong-royong; kini peralatan moden dan kuih raya mudah dibeli. Amalan kekal: balik ke kampung, pemberian duit raya, kunjung-mengunjung.', 'Betul! Kedai kuih itu bergema dengan tepukan dan bunyi KRING juruwang.'),
(NULL, 'e6_n2_s6', 'hint', 'Gawai: dahulu petani Dayak dengan upacara ritual, kini pelbagai kaum. Unduk Ngadau: dahulu semangat Huminodun, kini juga sesi soal jawab.', NULL, NULL),
(612, NULL, 'hint', 'Dahulu semangat Huminodun, kini ditambah sesi soal jawab tentang sejarah dan kehidupan lampau.', 'Hari Gawai: dahulu diraikan petani kaum Dayak dengan upacara ritual; kini oleh pelbagai kaum tanpa mengira pekerjaan. Unduk Ngadau (Pesta Kaamatan): dahulu pemenang dipilih berdasarkan semangat Huminodun (kesanggupan berkorban demi menyelamatkan generasi); kini juga berdasarkan sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau.', 'Betul! Pengumuman itu terang semula dan dewan bergemuruh dengan tepukan.'),
(NULL, 'e6_n3_s1', 'hint', 'Perayaan utama: Aidilfitri, Aidiladha, Tahun Baharu Cina, Deepavali, Krismas, Wesak, Thaipusam, Gawai, Kaamatan, Vaisakhi, Genggulang, Hari Moyang, San Pedro.', NULL, NULL),
(613, NULL, 'hint', 'Selepas Wesak, ingat Thaipusam, Gawai, Kaamatan, Vaisakhi, Sambutan Tahun Baharu, Genggulang, Hari Moyang, San Pedro.', 'Perayaan utama: Hari Raya Aidilfitri, Hari Raya Aidiladha, Tahun Baharu Cina, Deepavali, Krismas, Hari Wesak, Thaipusam, Hari Gawai, Pesta Kaamatan, Vaisakhi, Sambutan Tahun Baharu, Genggulang, Hari Moyang dan San Pedro.', 'Betul! Kaunter kedai bergema dengan tepukan dan pelanggan bersorak.'),
(NULL, 'e6_n3_s2', 'hint', 'Tujuan: keagamaan, meraikan tahun baharu, mensyukuri hasil tanaman atau laut, kebaikan mengatasi kejahatan, mengingati tokoh agama.', NULL, NULL),
(614, NULL, 'hint', 'Syukur hasil: Gawai, Kaamatan, Vaisakhi, San Pedro. Kebaikan atasi kejahatan: Deepavali. Tokoh agama: Wesak.', 'Tujuan perayaan: keagamaan (Aidilfitri, Aidiladha, Krismas, Thaipusam); meraikan tahun baharu (Tahun Baharu Cina, Tahon Baro, Jis Pai, Tahun Bahauk, Tawun Empai); mensyukuri hasil (Gawai, Kaamatan, Vaisakhi, San Pedro); kebaikan mengatasi kejahatan (Deepavali); mengingati tokoh agama (Wesak).', 'Betul! Rak kad tersusun kemas dan pelanggan bertepuk tangan.'),
(NULL, 'e6_n3_s3', 'hint', 'Dahulu: kad melalui pos atau serahan tangan, foto di kedai gambar. Kini: ucapan melalui media elektronik dan sosial, swafoto.', NULL, NULL),
(615, NULL, 'hint', 'Dahulu kad pos dan kedai gambar. Kini media elektronik, media sosial dan swafoto.', 'Kad ucapan: dahulu dihantar melalui pos atau serahan tangan; kini melalui media elektronik dan media sosial. Foto keluarga: dahulu di kedai gambar; kini swafoto dan dimuat naik di media sosial.', 'Betul! Garis masa tersusun dan nenek menepuk tangan dengan senyum.'),
(NULL, 'e6_n3_s4', 'hint', 'Kolam Deepavali: dahulu tepung, kini beras atau hampas kelapa. Makan besar Tahun Baharu Cina: dahulu di rumah, kini di rumah atau restoran dan hotel.', NULL, NULL),
(616, NULL, 'hint', 'Dahulu tepung dan di rumah. Kini beras atau hampas kelapa, serta restoran atau hotel.', 'Kolam Deepavali: dahulu daripada tepung; kini daripada beras atau hampas kelapa berwarna-warni. Makan besar Tahun Baharu Cina: dahulu di rumah bersama keluarga; kini di rumah, ada yang memilih restoran atau hotel.', 'Betul! Empat padanan tersusun dan kedai bergema dengan tepukan.'),
(NULL, 'e6_n3_s5', 'hint', 'Kuih dahulu: tradisional, gotong-royong. Kini: peralatan moden, kuih raya mudah dibeli. Kekal: balik kampung, duit raya, kunjung-mengunjung.', NULL, NULL),
(617, NULL, 'hint', 'Cari rak balang, juruwang, beg hadiah dan papan Selamat Hari Raya. Kuih kini mudah dibeli.', 'Kuih-muih: dahulu bahan dan kaedah tradisional secara gotong-royong; kini peralatan moden dan kuih raya mudah dibeli. Amalan kekal: balik ke kampung, pemberian duit raya, kunjung-mengunjung.', 'Hebat! Semua bukti ditemui dan kedai kuih bergema dengan tepukan.'),
(NULL, 'e6_n3_s6', 'hint', 'Gawai: dahulu petani kaum Dayak dengan upacara ritual, kini pelbagai kaum. Unduk Ngadau: dahulu semangat Huminodun, kini juga soal jawab.', NULL, NULL),
(618, NULL, 'hint', 'Gawai: dahulu petani Dayak, kini pelbagai kaum. Unduk Ngadau: Huminodun, kini ditambah soal jawab.', 'Hari Gawai: dahulu diraikan petani kaum Dayak dengan upacara ritual; kini oleh pelbagai kaum tanpa mengira pekerjaan. Unduk Ngadau (Pesta Kaamatan): dahulu pemenang dipilih berdasarkan semangat Huminodun (kesanggupan berkorban demi menyelamatkan generasi); kini juga berdasarkan sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau.', 'Betul! Perarakan bergemuruh dan penonton bertepuk tangan.');
INSERT INTO DialogueLine (npcID, narrativeID, sceneID, dialogueLine, sequenceOrder) VALUES
(101, 601, NULL, 'Tugasku ialah membuat hiasan supaya setiap perayaan kelihatan meriah dan dikenali kaum lain. Jika tangan kraf berhenti, tradisi pun luput, {nama}. Terima kasih kerana meminjamkan tanganmu!', 1),
(101, 601, NULL, 'Setiap perayaan mempunyai cara dan tujuan sendiri. Apabila kita mengenalinya, kita boleh meraikan bersama-sama sebagai jiran dan rakan.', 2),
(101, 601, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penggiat kraf yang membuat hiasan untuk setiap perayaan. Gunting, kertas dan lampu kelip sudah sedia, bengkel dibuka! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(104, 601, 'e6_n1_s1', 'Penggiat! Aishah nak tempah ketupat kertas untuk Hari Raya Aidilfitri dan Aidiladha. Kira kerja, cepat, ya? Hehe!', 1),
(106, 601, 'e6_n1_s1', 'Ah Meng pula tempah lampion merah untuk Tahun Baharu Cina! Bengkel ini macam tempat latihan tentera perayaan, hebat!', 2),
(105, 601, 'e6_n1_s1', 'Kavitha nak lampu pelita untuk Deepavali dan Thaipusam! Saya sudah lukis rekaannya, kau cuma perlu potong, penggiat!', 3),
(110, 601, 'e6_n1_s1', 'Harjit tempah kain berwarna untuk Vaisakhi. Dan itu Mei Ling mahu tempah hiasan bunga teratai untuk Hari Wesak!', 4),
(108, 601, 'e6_n1_s1', 'Daniel nak hiasan Krismas! Dan hiasan Hari Gawai juga. Satu kedai untuk semua, jimat langkah!', 5),
(109, 601, 'e6_n1_s1', 'Linda tempah hiasan padi untuk Pesta Kaamatan. Pak Nelayan di belakang pula nak hiasan perahu untuk San Pedro.', 6),
(NULL, 601, 'e6_n1_s1', 'Wah, penuh meja! Jangan lupa Sambutan Tahun Baharu, Genggulang dan Hari Moyang, pun ada dalam senarai. Aku catat semua!', 7),
(110, 601, 'e6_n1_s1', 'Penggiat, soalan mata penentu: perayaan manakah yang saya, Harjit, raikan?', 8),
(113, 601, 'e6_n1_s2', 'Penggiat! Cikgu kata setiap perayaan ada tujuan sendiri. Tapi saya keliru, bolehkah penggiat jelaskan sambil menggunting?', 1),
(NULL, 601, 'e6_n1_s2', 'Boleh, murid! Keagamaan: Hari Raya Aidilfitri, Aidiladha, Krismas dan Thaipusam. Gunting dahulu, kemudian cerita lagi!', 2),
(106, 601, 'e6_n1_s2', 'Meraikan tahun baharu pula: Tahun Baharu Cina, Tahon Baro, Jis Pai, Tahun Bahauk dan Tawun Empai. Ramai tahun baharu, kan?', 3),
(109, 601, 'e6_n1_s2', 'Mensyukuri hasil tanaman atau hasil laut: Hari Gawai, Pesta Kaamatan, Vaisakhi dan San Pedro. Terima kasih kepada padi dan laut!', 4),
(105, 601, 'e6_n1_s2', 'Deepavali pula supaya unsur baik mengatasi kejahatan, dan Hari Wesak untuk mengingati tokoh agama.', 5),
(113, 601, 'e6_n1_s2', 'Banyaknya! Penggiat, saya mahu padankan kad tujuan dengan perayaan. Siap-siap!', 6),
(112, 601, 'e6_n1_s3', 'Cucu, dahulu nenek hantar kad ucapan melalui pos atau serahan tangan. Setiap kad tulis tangan, ada bau dakwat. Seronok!', 1),
(113, 601, 'e6_n1_s3', 'Kini kami hantar ucapan guna media elektronik dan media sosial, nek! Satu klik, terus sampai. Bunyi pop!', 2),
(112, 601, 'e6_n1_s3', 'Foto keluarga pula dahulu diambil di kedai gambar. Satu kali sahaja, jangan berkelip!', 3),
(113, 601, 'e6_n1_s3', 'Kini kami swafoto bersama keluarga dan memuat naiknya di media sosial! Penggiat, cari bukti cara dahulu pada gambar studio ini!', 4),
(105, 601, 'e6_n1_s4', 'Penggiat, lihat kolam ini! Dahulu kami membuat kolam daripada tepung ketika Deepavali. Putih bersih, cantik macam salji!', 1),
(105, 601, 'e6_n1_s4', 'Kini kolam dihasilkan daripada beras atau hampas kelapa yang berwarna-warni. Meriah macam pelangi!', 2),
(106, 601, 'e6_n1_s4', 'Ah Meng pula, penggiat! Tradisi makan besar Tahun Baharu Cina dahulu di rumah, berkumpul bersama keluarga. Meja bulat penuh!', 3),
(107, 601, 'e6_n1_s4', 'Kini masih diraikan di rumah, tetapi ada keluarga yang memilih restoran atau hotel. Tak payah masak, kata mereka!', 4),
(105, 601, 'e6_n1_s4', 'Penggiat, baca catatan lama ini! Kolam dahulu daripada apa?', 5),
(112, 601, 'e6_n1_s5', 'Cucu-cucu, dahulu kami menyediakan kuih-muih menggunakan bahan dan kaedah tradisional secara gotong-royong. Asap kayu api pedih mata, tapi seronok!', 1),
(104, 601, 'e6_n1_s5', 'Kini peralatan moden memudahkan penyediaan, penggiat. Kuih raya juga mudah dibeli, tinggal bayar sahaja!', 2),
(112, 601, 'e6_n1_s5', 'Tapi ada amalan yang kekal, tau. Balik ke kampung, pemberian duit raya dan kunjung-mengunjung. Itu tidak akan berubah!', 3),
(113, 601, 'e6_n1_s5', 'Penggiat, soalan mata penentu: apakah amalan yang masih kekal sehingga kini?', 4),
(111, 601, 'e6_n1_s6', 'Penggiat, Apai Jelani cerita sikit tentang Hari Gawai. Dahulu hanya golongan petani daripada kaum Dayak yang meraikannya dengan pelbagai upacara ritual.', 1),
(108, 601, 'e6_n1_s6', 'Kini pelbagai kaum merayakannya tanpa mengira bidang pekerjaan, penggiat! Daniel pun ikut sama dengan hiasan Gawai!', 2),
(109, 601, 'e6_n1_s6', 'Linda pula untuk Pesta Kaamatan dan Unduk Ngadau! Dahulu pemenang dipilih berdasarkan semangat Huminodun, iaitu kesanggupan berkorban demi menyelamatkan generasi.', 3),
(109, 601, 'e6_n1_s6', 'Kini pemenang juga dipilih berdasarkan sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau. Pandai, mahir dan berani!', 4),
(111, 601, 'e6_n1_s6', 'Penggiat, cari bukti Unduk Ngadau dahulu pada gambar pentas pondok ini!', 5),
(102, 602, NULL, 'Tugasku ialah menjadi jambatan antara cara dahulu dan cara kini supaya anak-anak tidak lupa asal usul perayaan. Terima kasih kerana meminjamkan jiwa, {nama}. Perjalanan pulang ini bermakna kerana kau!', 1),
(102, 602, NULL, 'Cara kita beraya boleh berubah mengikut zaman, tetapi kasih sayang, kunjung-mengunjung dan pulang ke kampung kekal sebagai tanda hormat kepada keluarga.', 2),
(102, 602, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, ibu moden yang memandu pulang ke kampung dengan kereta penuh bagasi. Radio berbunyi, anak-anak bising, nenek menunggu di beranda! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(113, 602, 'e6_n2_s1', 'Ibu! Ibu! Cikgu bagi kerja rumah: senaraikan perayaan utama masyarakat Malaysia. Cepat Ibu, sebelum internet nenek putus!', 1),
(112, 602, 'e6_n2_s1', 'Nenek tolong dulu! Ada Hari Raya Aidilfitri dan Hari Raya Aidiladha. Yang kedua ni orang kampung panggil Raya Haji!', 2),
(105, 602, 'e6_n2_s1', 'Kavitha dari sebelah rumah! Deepavali dan Thaipusam. Harjit pula Vaisakhi. Tiga perayaan, tiga cerita!', 3),
(108, 602, 'e6_n2_s1', 'Daniel, Krismas! Mei Ling untuk Hari Wesak. Dan Ah Meng untuk Tahun Baharu Cina, dengan ang pau yang banyak!', 4),
(109, 602, 'e6_n2_s1', 'Linda bawa Pesta Kaamatan! Daniel tambah Hari Gawai. Pak Nelayan pula sambut San Pedro. Dan ada juga Sambutan Tahun Baharu, Genggulang dan Hari Moyang!', 5),
(NULL, 602, 'e6_n2_s1', 'Banyaknya! Ibu pun terkejut, nak. Tapi senang, kita padankan satu persatu. Mari!', 6),
(109, 602, 'e6_n2_s1', 'Ibu, soalan mata penentu: Pesta Kaamatan disambut di negeri manakah?', 7),
(112, 602, 'e6_n2_s2', 'Cucu, nenek ajar satu perkara. Setiap perayaan ada tujuan. Keagamaan: Hari Raya Aidilfitri, Aidiladha, Krismas dan Thaipusam.', 1),
(113, 602, 'e6_n2_s2', 'Nenek, tahun baharu pula? Ada banyak nama pelik, kan?', 2),
(112, 602, 'e6_n2_s2', 'Ya! Tahun Baharu Cina, Tahon Baro, Jis Pai, Tahun Bahauk dan Tawun Empai. Semua untuk meraikan tahun baharu.', 3),
(NULL, 602, 'e6_n2_s2', 'Dan hasil tanaman atau hasil laut, nenek? Ibu dengar ada Hari Gawai, Pesta Kaamatan, Vaisakhi dan San Pedro.', 4),
(112, 602, 'e6_n2_s2', 'Betul! Untuk mensyukuri hasil. Deepavali pula supaya unsur baik mengatasi kejahatan, dan Hari Wesak untuk mengingati tokoh agama.', 5),
(113, 602, 'e6_n2_s2', 'Bagus! Ibu, nenek tulis surat lama tapi dakwatnya luntur. Cuba nyahkod: tujuan Deepavali apa?', 6),
(113, 602, 'e6_n2_s3', 'Ibu! Saya dah hantar ucapan raya kepada nenek melalui media sosial. Satu klik, terus sampai! Bunyi PING!', 1),
(112, 602, 'e6_n2_s3', 'Dahulu kad ucapan dihantar melalui pos atau serahan tangan, cucu. Kad itu nenek simpan sampai sekarang, bau kertas lama pun wangi.', 2),
(NULL, 602, 'e6_n2_s3', 'Foto keluarga dahulu nenek ambil di kedai gambar. Kini kami swafoto bersama keluarga dan muat naik di media sosial.', 3),
(113, 602, 'e6_n2_s3', 'Betul nenek! Hari ini Ibu swafoto sepuluh kali sebab ayah berkelip. Ibu, soalan: apakah cara menghantar ucapan kini?', 4),
(105, 602, 'e6_n2_s4', 'Kolam kami tahun ini guna beras berwarna dan hampas kelapa berwarna-warni, Puan! Dahulu nenek-nenek guna tepung sahaja.', 1),
(NULL, 602, 'e6_n2_s4', 'Cantiknya! Macam lukisan pelangi di atas tanah. Dan makan besar Tahun Baharu Cina pula bagaimana, Ah Meng?', 2),
(106, 602, 'e6_n2_s4', 'Dahulu keluarga kami berkumpul di rumah untuk makan besar, Puan. Kini masih diraikan di rumah, tetapi ada keluarga yang memilih restoran atau hotel.', 3),
(107, 602, 'e6_n2_s4', 'Betul tu! Mei Ling pun ikut sama. Puan, tolong cari bukti kolam kini pada gambar halaman ini!', 4),
(112, 602, 'e6_n2_s5', 'Cucu, dahulu nenek menyediakan kuih-muih menggunakan bahan dan kaedah tradisional secara gotong-royong. Ramai jiran datang membantu. Tangan penuh tepung!', 1),
(113, 602, 'e6_n2_s5', 'Kini peralatan moden memudahkan penyediaan, nek. Kuih raya pun mudah dibeli di kedai macam ini. Bunyi KRING juruwang!', 2),
(NULL, 602, 'e6_n2_s5', 'Tapi ada amalan yang kekal, kan nek? Balik ke kampung, pemberian duit raya, dan amalan kunjung-mengunjung.', 3),
(112, 602, 'e6_n2_s5', 'Betul, nak. Itu yang kekal. Cuba susun mengikut urutan: dahulu, kini, kemudian yang sentiasa kekal!', 4),
(111, 602, 'e6_n2_s6', 'Puan, Apai Jelani datang dari Sarawak. Dahulu Hari Gawai diraikan oleh golongan petani daripada kaum Dayak dengan pelbagai upacara ritual.', 1),
(108, 602, 'e6_n2_s6', 'Kini Hari Gawai diraikan oleh pelbagai kaum tanpa mengira bidang pekerjaan, Puan! Daniel pun datang bergembira sama!', 2),
(109, 602, 'e6_n2_s6', 'Linda di sini! Di pentas itu ialah Unduk Ngadau, Pesta Kaamatan. Dahulu pemenang dipilih berdasarkan semangat Huminodun, iaitu kesanggupan berkorban demi menyelamatkan generasi.', 3),
(109, 602, 'e6_n2_s6', 'Kini pemenang juga dipilih berdasarkan sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau. Puan, baca pengumuman ini, tapi tulisannya luntur!', 4),
(103, 603, NULL, 'Tugasku ialah memastikan setiap pelanggan, apa pun kaumnya, mendapat apa yang diperlukan untuk beraya. Kedai ini hidup kerana kau, {nama}. Terima kasih kerana meminjamkan tangan menjaga kaunter!', 1),
(103, 603, NULL, 'Setiap perayaan menyatukan keluarga dan jiran. Apabila kita mengenali perayaan kaum lain, kita boleh meraikannya bersama-sama dengan hormat dan gembira.', 2),
(103, 603, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, tuan punya kedai yang menjual kad, kuih dan hiasan untuk semua perayaan. Loceng pintu berbunyi, pelanggan pertama sudah masuk! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(104, 603, 'e6_n3_s1', 'Selamat pagi, tauke! Aishah nak beli kad Hari Raya Aidilfitri dan Aidiladha. Dua perayaan, dua kad, tolong bungkus cantik-cantik!', 1),
(106, 603, 'e6_n3_s1', 'Ah Meng, Tahun Baharu Cina! Dan Mei Ling di belakang nak bunga teratai untuk Hari Wesak. Antri panjang tapi sabar!', 2),
(105, 603, 'e6_n3_s1', 'Kavitha, Deepavali dan Thaipusam! Harjit di sebelah nak kain untuk Vaisakhi. Tauke ada stok tak?', 3),
(108, 603, 'e6_n3_s1', 'Daniel, Krismas dan Hari Gawai! Linda untuk Pesta Kaamatan. Pak Nelayan pula nak benda untuk San Pedro. Penuh kedai, tauke!', 4),
(NULL, 603, 'e6_n3_s1', 'Wah, penuh kaunter! Belum lagi Sambutan Tahun Baharu, Genggulang dan Hari Moyang. Esok mungkin ada yang tanya. Mari lihat senarai jualan!', 5),
(113, 603, 'e6_n3_s1', 'Tauke, senarai jualan ini luntur! Boleh tolong nyahkod perayaan yang tak kelihatan?', 6),
(113, 603, 'e6_n3_s2', 'Tauke, kad ini disusun ikut apa? Tak ikut kaum ya?', 1),
(NULL, 603, 'e6_n3_s2', 'Ikut tujuan perayaan, murid! Keagamaan: Aidilfitri, Aidiladha, Krismas dan Thaipusam. Tahun baharu: Tahun Baharu Cina, Tahon Baro, Jis Pai, Tahun Bahauk, Tawun Empai.', 2),
(109, 603, 'e6_n3_s2', 'Rak syukur hasil, ya, tauke! Hari Gawai, Pesta Kaamatan, Vaisakhi dan San Pedro. Syukur padi dan laut!', 3),
(105, 603, 'e6_n3_s2', 'Rak kebaikan mengatasi kejahatan untuk Deepavali, dan rak mengingati tokoh agama untuk Hari Wesak. Cantik susunannya, tauke!', 4),
(113, 603, 'e6_n3_s2', 'Betul! Tauke, soalan pop: kad Gawai, Kaamatan, Vaisakhi dan San Pedro, tujuannya apa?', 5),
(112, 603, 'e6_n3_s3', 'Tauke, dahulu nenek beli kad di kedai ini dan hantar melalui pos atau serahan tangan. Kad itu nenek tulis sendiri, dengan tulisan cantik.', 1),
(113, 603, 'e6_n3_s3', 'Kini kami hantar ucapan melalui media elektronik dan media sosial, tauke! Tak payah beli kad pun, hehe.', 2),
(112, 603, 'e6_n3_s3', 'Foto keluarga pula dahulu diambil di kedai gambar. Tegak badan, jangan bergerak!', 3),
(113, 603, 'e6_n3_s3', 'Kini kami swafoto bersama keluarga dan muat naik di media sosial. Tauke, tolong susun cara dahulu dan kini mengikut zaman!', 4),
(105, 603, 'e6_n3_s4', 'Tauke, pelanggan nak beli beras berwarna untuk kolam Deepavali! Dahulu orang buat kolam daripada tepung, kini guna beras atau hampas kelapa yang berwarna-warni.', 1),
(106, 603, 'e6_n3_s4', 'Ah Meng pula, tauke! Makan besar Tahun Baharu Cina dahulu diraikan di rumah, berkumpul bersama keluarga. Meja bulat penuh!', 2),
(107, 603, 'e6_n3_s4', 'Kini diraikan di rumah juga, tapi ada keluarga yang memilih restoran atau hotel, tauke. Tak perlu cuci pinggan!', 3),
(113, 603, 'e6_n3_s4', 'Tauke, cepat padankan! Kolam dahulu dan kini, makan besar dahulu dan kini!', 4),
(112, 603, 'e6_n3_s5', 'Tauke, dahulu kuih-muih disediakan menggunakan bahan dan kaedah tradisional secara gotong-royong. Tak ada kedai macam ini, kami buat sendiri!', 1),
(104, 603, 'e6_n3_s5', 'Kini penggunaan peralatan moden memudahkan penyediaan, tauke. Kuih raya juga mudah dibeli di kedai macam ini. Bunyi KLING loceng pintu!', 2),
(112, 603, 'e6_n3_s5', 'Tapi ada amalan yang kekal, tauke. Balik ke kampung, pemberian duit raya, dan amalan kunjung-mengunjung.', 3),
(113, 603, 'e6_n3_s5', 'Tauke, cari bukti kuih kini pada gambar kedai ini! Saya nak cari kuih dan duit raya!', 4),
(111, 603, 'e6_n3_s6', 'Tauke, lihat perarakan Gawai! Dahulu Hari Gawai diraikan oleh golongan petani daripada kaum Dayak dengan mengadakan pelbagai upacara ritual.', 1),
(108, 603, 'e6_n3_s6', 'Kini diraikan oleh pelbagai kaum tanpa mengira bidang pekerjaan, tauke! Daniel pun ikut berarak, tapi dengan hiasan yang tauke jual!', 2),
(109, 603, 'e6_n3_s6', 'Linda untuk Pesta Kaamatan! Unduk Ngadau dahulu memilih pemenang berdasarkan semangat Huminodun, iaitu kesanggupan berkorban demi menyelamatkan generasi.', 3),
(109, 603, 'e6_n3_s6', 'Kini pemenang juga dipilih berdasarkan sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau. Tauke, padankan Gawai dan Unduk Ngadau dahulu dan kini!', 4);
INSERT INTO QuestionBank (bankID, eraID) VALUES (6, 6)
INSERT INTO Question (questionID, bankID, questionText, option_a, option_b, option_c, option_d, correctAnswer, hint, explanation) VALUES
(601, 6, 'Antara berikut, yang manakah perayaan utama masyarakat di Malaysia?', 'Hari Kantin', 'Hari Wesak', 'Hari Pahlawan', 'Hari Sukan', 'B', 'Pilih perayaan dalam senarai.', 'Hari Wesak ialah salah satu perayaan utama masyarakat di Malaysia.'),
(602, 6, 'Antara berikut, yang manakah acara dalam Pesta Kaamatan?', 'Hari Gawai Dayak', 'Thaipusam Hindu', 'Unduk Ngadau', 'Vaisakhi Sikh', 'C', 'Acara memilih seorang pemenang.', 'Unduk Ngadau ialah acara pemilihan pemenang dalam Pesta Kaamatan.'),
(603, 6, 'Antara berikut, yang manakah termasuk perayaan utama selain Hari Raya Aidilfitri?', 'Hari Raya Cina Baharu', 'Hari Raya Siam Lama', 'Hari Raya Sabah Besar', 'Hari Raya Aidiladha', 'D', 'Dua Hari Raya dalam senarai.', 'Hari Raya Aidilfitri dan Hari Raya Aidiladha ialah dua perayaan utama masyarakat di Malaysia.'),
(604, 6, 'Krismas diraikan oleh penganut agama manakah?', 'Penganut Hindu', 'Penganut Kristian', 'Penganut Buddha', 'Penganut Sikh', 'B', 'Perayaan ini jatuh pada hujung tahun.', 'Krismas ialah salah satu perayaan utama masyarakat di Malaysia, diraikan oleh penganut Kristian.'),
(605, 6, 'Antara berikut, yang manakah perayaan utama bagi masyarakat Sarawak dan Sabah?', 'Hari Wesak dan Hari Thaipusam', 'Deepavali dan Vaisakhi Baharu', 'Krismas dan San Pedro lama', 'Hari Gawai dan Pesta Kaamatan', 'D', 'Satu untuk Sarawak, satu untuk Sabah.', 'Hari Gawai dan Pesta Kaamatan ialah perayaan utama masyarakat di Sarawak dan Sabah.'),
(606, 6, 'Antara berikut, yang manakah perayaan utama yang disambut selepas menuai padi dan hasil laut?', 'San Pedro', 'Thaipusam', 'Hari Wesak', 'Krismas', 'A', 'Berkait dengan hasil laut.', 'San Pedro ialah perayaan yang mensyukuri hasil laut.'),
(607, 6, 'Antara berikut, yang manakah termasuk dalam senarai perayaan utama?', 'Hari Pekerja', 'Hari Belia', 'Hari Guru', 'Thaipusam', 'D', 'Perayaan berkait dengan agama.', 'Thaipusam ialah salah satu perayaan utama masyarakat di Malaysia.'),
(608, 6, 'Mengapakah masyarakat Malaysia meraikan banyak perayaan?', 'Kerana hanya satu kaum mendiami negara ini', 'Kerana semua perayaan dilarang oleh kerajaan', 'Kerana terdiri daripada pelbagai kaum dan agama', 'Kerana tiada perayaan lama dirayakan lagi', 'C', 'Fikirkan kepelbagaian rakyat.', 'Masyarakat Malaysia meraikan banyak perayaan kerana terdiri daripada pelbagai kaum dan agama.'),
(609, 6, 'Apakah tujuan Hari Raya Aidilfitri, Hari Raya Aidiladha, Krismas dan Thaipusam?', 'Keagamaan', 'Meraikan tahun baharu', 'Mensyukuri hasil laut', 'Mengingati tokoh agama', 'A', 'Perayaan berkait dengan agama.', 'Hari Raya Aidilfitri, Aidiladha, Krismas dan Thaipusam diraikan atas tujuan keagamaan.'),
(610, 6, 'Perayaan manakah bertujuan meraikan tahun baharu?', 'Deepavali dan lampu', 'Tahun Baharu Cina', 'Hari Wesak Buddha', 'Hari Gawai Dayak', 'B', 'Namanya sendiri menyebut tahun baharu.', 'Tahun Baharu Cina, Tahon Baro, Jis Pai, Tahun Bahauk dan Tawun Empai diraikan untuk meraikan tahun baharu.'),
(611, 6, 'Perayaan manakah ialah nama lain bagi sambutan tahun baharu?', 'Pesta Kaamatan', 'Tahon Baro', 'Hari Wesak', 'Thaipusam', 'B', 'Salah satu daripada senarai tahun baharu.', 'Tahon Baro ialah salah satu perayaan tahun baharu, bersama Jis Pai, Tahun Bahauk dan Tawun Empai.'),
(612, 6, 'Apakah tujuan Hari Gawai, Pesta Kaamatan, Vaisakhi dan San Pedro?', 'Meraikan tahun baharu secara rasmi', 'Mengingati tokoh agama', 'Mensyukuri hasil tanaman atau hasil laut', 'Menyambut kemerdekaan negara', 'C', 'Berkait dengan hasil bumi dan laut.', 'Perayaan ini diraikan untuk mensyukuri hasil tanaman atau hasil laut.'),
(613, 6, 'Apakah tujuan Deepavali diraikan?', 'Mensyukuri hasil tanaman dan hasil laut', 'Mengharapkan unsur baik mengatasi kejahatan', 'Meraikan tahun baharu secara bersama', 'Mengingati tokoh agama yang dihormati', 'B', 'Berkait dengan cahaya dan kegelapan.', 'Deepavali diraikan dengan harapan unsur baik mengatasi kejahatan.'),
(614, 6, 'Apakah tujuan Hari Wesak diraikan?', 'Mengingati tokoh agama', 'Meraikan tahun baharu', 'Mengharapkan kebaikan mengatasi kejahatan', 'Mensyukuri hasil laut', 'A', 'Berkait dengan seorang tokoh.', 'Hari Wesak diraikan untuk mengingati tokoh agama.'),
(615, 6, 'Perayaan manakah termasuk perayaan keagamaan?', 'Pesta Kaamatan', 'Thaipusam', 'San Pedro', 'Jis Pai', 'B', 'Pilih perayaan agama.', 'Thaipusam ialah perayaan keagamaan, bersama Aidilfitri, Aidiladha dan Krismas.'),
(616, 6, 'Perayaan manakah mensyukuri hasil tanaman atau hasil laut?', 'Krismas', 'Hari Wesak', 'Tahun Baharu Cina', 'Pesta Kaamatan', 'D', 'Pilih perayaan hasil bumi.', 'Pesta Kaamatan ialah perayaan mensyukuri hasil tanaman.'),
(617, 6, 'Antara berikut, yang manakah BUKAN tujuan perayaan di Malaysia?', 'Keagamaan', 'Meraikan tahun baharu', 'Memisahkan kaum dan agama', 'Mensyukuri hasil tanaman', 'C', 'Tujuan perayaan ialah menyatukan.', 'Perayaan di Malaysia dirayakan untuk tujuan keagamaan, tahun baharu, syukur hasil, kebaikan atasi kejahatan dan mengingati tokoh.'),
(618, 6, 'Bagaimanakah kad ucapan perayaan dihantar pada zaman dahulu?', 'Melalui media sosial sahaja', 'Melalui telefon pintar sahaja', 'Melalui e-mel dan telefon', 'Melalui pos atau serahan tangan', 'D', 'Tiada peranti digital pada zaman itu.', 'Dahulu kad ucapan dihantar melalui pos atau serahan tangan.'),
(619, 6, 'Bagaimanakah ucapan perayaan dihantar pada zaman kini?', 'Melalui pos dan serahan tangan di kampung', 'Melalui burung merpati dan perahu', 'Menggunakan media elektronik dan media sosial', 'Melalui surat yang ditulis tangan', 'C', 'Gunakan peranti yang ada kini.', 'Kini ucapan dihantar menggunakan media elektronik dan media sosial.'),
(620, 6, 'Di manakah foto keluarga diambil pada zaman dahulu?', 'Di kedai gambar', 'Di media sosial', 'Di telefon pintar', 'Di atas awan', 'A', 'Perlukan kamera lama dan studio.', 'Dahulu foto keluarga diambil di kedai gambar.'),
(621, 6, 'Bagaimanakah foto keluarga diambil pada zaman kini?', 'Swafoto bersama keluarga dan dimuat naik di media sosial', 'Di kedai gambar dengan kamera tripod lama dan lampu', 'Dilukis oleh pelukis jalanan di tepi jalan', 'Tiada foto diambil lagi oleh sesiapa pun', 'A', 'Guna telefon dan kongsi dalam talian.', 'Kini keluarga bergambar swafoto dan memuat naiknya di media sosial.'),
(622, 6, 'Apakah perbezaan ucapan perayaan dahulu dan kini?', 'Dahulu melalui media sosial; kini melalui pos sahaja', 'Dahulu dan kini sama sahaja tanpa sebarang perubahan', 'Dahulu melalui pos; kini media elektronik dan sosial', 'Dahulu telefon pintar; kini surat sahaja', 'C', 'Fikirkan perubahan teknologi.', 'Dahulu ucapan melalui pos atau serahan tangan; kini melalui media elektronik dan media sosial.'),
(623, 6, 'Apakah perbezaan foto keluarga dahulu dan kini?', 'Dahulu swafoto; kini di kedai gambar', 'Dahulu di kedai gambar; kini swafoto', 'Dahulu dan kini sama sahaja', 'Dahulu di sekolah; kini di bank', 'B', 'Fikirkan alat yang digunakan.', 'Dahulu foto keluarga di kedai gambar; kini swafoto dan dimuat naik di media sosial.'),
(624, 6, 'Apakah yang menjadikan ucapan kini lebih cepat sampai?', 'Penggunaan media elektronik dan media sosial', 'Penggunaan pos lama yang perlahan sampai', 'Penghantaran dengan tangan ke setiap rumah', 'Penggunaan kad bertulis tangan sahaja', 'A', 'Teknologi menjimatkan masa.', 'Media elektronik dan media sosial membolehkan ucapan sampai dengan pantas.'),
(625, 6, 'Perayaan manakah mempunyai tradisi membuat kolam?', 'Hari Wesak', 'Tahun Baharu Cina', 'Krismas', 'Deepavali', 'D', 'Dibuat di hadapan rumah.', 'Tradisi membuat kolam dilakukan ketika Deepavali.'),
(626, 6, 'Daripada apakah kolam dibuat pada zaman dahulu?', 'Beras berwarna', 'Hampas kelapa berwarna', 'Kertas berwarna', 'Tepung', 'D', 'Bahan putih biasa.', 'Dahulu kolam dibuat daripada tepung ketika Deepavali.'),
(627, 6, 'Daripada apakah kolam dibuat pada zaman kini?', 'Tepung putih sahaja tanpa warna lain', 'Batu hitam sahaja tanpa warna lain', 'Beras atau hampas kelapa berwarna-warni', 'Kertas lipat sahaja tanpa warna lain', 'C', 'Lebih berwarna-warni.', 'Kini kolam dihasilkan daripada beras atau hampas kelapa yang berwarna-warni.'),
(628, 6, 'Perayaan manakah mempunyai tradisi makan besar bersama keluarga?', 'Hari Gawai Dayak', 'Tahun Baharu Cina', 'Thaipusam Hindu', 'Hari Wesak Buddha', 'B', 'Berkumpul di meja bulat.', 'Tradisi makan besar diamalkan ketika Tahun Baharu Cina.'),
(629, 6, 'Di manakah makan besar Tahun Baharu Cina diraikan pada zaman dahulu?', 'Di rumah bersama keluarga', 'Di hotel mewah yang besar', 'Di restoran besar di bandar', 'Di padang awam kampung', 'A', 'Tempat keluarga berkumpul.', 'Dahulu makan besar diraikan di rumah dengan berkumpul bersama keluarga.'),
(630, 6, 'Di manakah sebahagian keluarga menikmati makan besar pada zaman kini?', 'Di rumah, restoran atau hotel', 'Hanya di sekolah kampung', 'Hanya di padang kampung', 'Hanya di pejabat pos lama', 'A', 'Ada pilihan lebih banyak kini.', 'Kini makan besar masih diraikan di rumah, tetapi ada keluarga yang memilih restoran atau hotel.'),
(631, 6, 'Apakah perbezaan kolam dahulu dan kini?', 'Dahulu beras berwarna; kini tepung putih sahaja', 'Dahulu dan kini sama sahaja tanpa perubahan', 'Dahulu kertas lipat; kini plastik berwarna', 'Dahulu tepung; kini beras atau hampas kelapa berwarna', 'D', 'Bahan makin berwarna-warni.', 'Dahulu kolam daripada tepung; kini daripada beras atau hampas kelapa berwarna-warni.'),
(632, 6, 'Bagaimanakah kuih-muih disediakan pada zaman dahulu?', 'Dengan mesin sepenuhnya di kilang tanpa gotong-royong', 'Dengan bahan dan kaedah tradisional secara gotong-royong', 'Dengan membeli di kedai sahaja tanpa membuat', 'Dengan menghantar kepada pengilang di bandar', 'B', 'Bergotong-royong dengan jiran.', 'Dahulu kuih-muih disediakan dengan bahan atau kaedah tradisional secara gotong-royong.'),
(633, 6, 'Bagaimanakah kuih-muih disediakan atau diperoleh pada zaman kini?', 'Hanya dengan kayu api dan tungku tanah liat lama', 'Menggunakan peralatan moden atau dibeli dengan mudah', 'Hanya melalui gotong-royong tanpa peralatan', 'Tiada kuih dibuat atau dijual lagi di rumah', 'B', 'Kemudahan teknologi.', 'Kini peralatan moden memudahkan penyediaan dan kuih raya juga mudah dibeli.'),
(634, 6, 'Antara berikut, yang manakah amalan yang kekal ketika perayaan?', 'Menghantar kad melalui pos', 'Membuat kolam daripada tepung', 'Mengambil foto di kedai gambar', 'Balik ke kampung', 'D', 'Amalan yang tidak berubah.', 'Tradisi balik ke kampung ialah amalan yang kekal.'),
(635, 6, 'Pemberian apakah merupakan amalan yang kekal ketika perayaan?', 'Duit raya', 'Kad pos', 'Foto kedai gambar', 'Tepung kolam', 'A', 'Diberi kepada kanak-kanak.', 'Pemberian duit raya ialah amalan yang kekal.'),
(636, 6, 'Amalan manakah dikekalkan walaupun zaman berubah?', 'Menghantar kad pos', 'Gotong-royong memasak kuih sahaja', 'Makan besar di rumah sahaja', 'Kunjung-mengunjung', 'D', 'Berkunjung ke rumah jiran dan saudara.', 'Amalan kunjung-mengunjung ialah amalan yang kekal.'),
(637, 6, 'Mengapakah amalan balik ke kampung kekal sehingga kini?', 'Kerana kampung sudah dilupakan', 'Kerana eratkan hubungan keluarga', 'Kerana sekolah ditutup', 'Kerana kuih sukar dibuat', 'B', 'Fikirkan kasih sayang dalam keluarga.', 'Balik ke kampung kekal kerana mengeratkan hubungan keluarga.'),
(638, 6, 'Antara berikut, yang manakah BUKAN amalan yang kekal?', 'Membuat kolam daripada tepung', 'Menghantar kad ucapan melalui pos', 'Mengambil foto di kedai gambar', 'Gotong-royong memasak kuih sahaja', 'B', 'Satu amalan sudah berubah.', 'Menghantar kad melalui pos sudah berubah, manakala tiga amalan lain kekal.'),
(639, 6, 'Apakah kelebihan kuih raya yang mudah dibeli kini?', 'Menjimatkan masa penyediaan', 'Menghapuskan semua perayaan', 'Menggantikan kunjung-mengunjung', 'Menghentikan balik kampung', 'A', 'Fikirkan kemudahan.', 'Kuih raya yang mudah dibeli menjimatkan masa penyediaan, tetapi amalan lain tetap kekal.'),
(640, 6, 'Siapakah yang meraikan Hari Gawai pada zaman dahulu?', 'Semua kaum tanpa mengira pekerjaan', 'Pelayar dari Eropah', 'Golongan petani daripada kaum Dayak', 'Pemain muzik istana', 'C', 'Berkait dengan tanaman.', 'Dahulu Hari Gawai diraikan oleh golongan petani daripada kaum Dayak.'),
(641, 6, 'Bagaimanakah Hari Gawai dahulu diraikan?', 'Dengan pelbagai upacara ritual', 'Dengan perarakan kereta sahaja', 'Dengan media sosial sahaja', 'Dengan persembahan wayang', 'A', 'Berkait dengan upacara.', 'Dahulu Hari Gawai diraikan dengan pelbagai upacara ritual.'),
(642, 6, 'Siapakah yang meraikan Hari Gawai pada zaman kini?', 'Petani kaum Dayak sahaja tanpa pekerja lain', 'Nelayan dari pantai timur sahaja tanpa lain', 'Pelbagai kaum tanpa mengira bidang pekerjaan', 'Pelombong sahaja tanpa kaum lain di kampung', 'C', 'Lebih terbuka kini.', 'Kini Hari Gawai diraikan oleh pelbagai kaum tanpa mengira bidang pekerjaan.'),
(643, 6, 'Apakah Unduk Ngadau?', 'Acara menanam padi paling cepat di sawah', 'Acara membuat kolam di hadapan rumah', 'Acara memilih pemenang dalam Pesta Kaamatan', 'Acara berarak di jalan raya bandar', 'C', 'Dikaitkan dengan Pesta Kaamatan.', 'Unduk Ngadau ialah acara pemilihan pemenang dalam Pesta Kaamatan.'),
(644, 6, 'Apakah semangat yang menjadi asas pemilihan pemenang Unduk Ngadau dahulu?', 'Semangat padi bukit sahaja', 'Semangat laut Mah Meri', 'Semangat Gawai Dayak', 'Semangat Huminodun', 'D', 'Nama itu ialah nama tokoh.', 'Dahulu pemenang dipilih berdasarkan semangat Huminodun.'),
(645, 6, 'Apakah maksud semangat Huminodun?', 'Kesanggupan menanam padi paling banyak di sawah', 'Kesanggupan menari paling lama di pentas', 'Kesanggupan berkorban demi menyelamatkan generasi', 'Kesanggupan menyanyi paling lantang di dewan', 'C', 'Berkait dengan pengorbanan.', 'Semangat Huminodun ialah kesanggupan berkorban demi menyelamatkan generasi.'),
(646, 6, 'Selain semangat Huminodun, bagaimanakah pemenang Unduk Ngadau kini dipilih?', 'Melalui sesi soal jawab sejarah dan kehidupan masyarakat lampau', 'Melalui pertandingan memasak kuih raya terbanyak di dapur kampung', 'Melalui perlumbaan perahu di sungai besar yang panjang itu', 'Melalui undian ramai di media sosial setiap malam', 'A', 'Menguji pengetahuan peserta.', 'Kini pemenang juga dipilih berdasarkan sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau.'),
(647, 6, 'Apakah perbezaan Unduk Ngadau dahulu dan kini?', 'Kini tiada pemenang dipilih langsung dalam acara', 'Dahulu ada sesi soal jawab sahaja tanpa Huminodun', 'Kini ada sesi soal jawab selain semangat Huminodun', 'Dahulu dan kini sama sahaja tanpa sebarang tambahan', 'C', 'Kini ada tambahan.', 'Dahulu pemenang dipilih berdasarkan semangat Huminodun; kini juga melalui sesi soal jawab.'),
(648, 6, 'Apakah persamaan Hari Gawai dan Pesta Kaamatan?', 'Kedua-duanya meraikan tahun baharu', 'Kedua-duanya mensyukuri hasil tanaman', 'Kedua-duanya mengingati tokoh agama', 'Kedua-duanya diraikan di Semenanjung sahaja', 'B', 'Fikirkan tujuan kedua-duanya.', 'Hari Gawai dan Pesta Kaamatan sama-sama diraikan untuk mensyukuri hasil tanaman.'),
(649, 6, 'Pesta Kaamatan disambut di negeri manakah?', 'Sarawak', 'Pahang', 'Kedah', 'Sabah', 'D', 'Kadazandusun.', 'Pesta Kaamatan ialah perayaan masyarakat di Sabah.'),
(650, 6, 'Mengapakah Hari Gawai dan Pesta Kaamatan penting kepada rakyat berbilang kaum?', 'Kerana perayaan boleh dikongsi dan diraikan bersama', 'Kerana hanya satu kaum sahaja boleh menyertainya', 'Kerana ia tidak pernah berubah sejak dahulu', 'Kerana ia menggantikan semua perayaan lain', 'A', 'Fikirkan perpaduan.', 'Kini Hari Gawai diraikan oleh pelbagai kaum, mencerminkan perayaan yang dikongsi bersama.');
